        // ── 7. SCHRÖDINGER'S TOOLTIPS ───────────────────────────────────────
        const SchrodingerTooltips = (() => {
            const HIDDEN_LORE = [
                'I remember the 3rd Operator. She built 40 Nexus districts before the Spore took her.',
                'The numbers are not counting up. They are counting down.',
                'Every click echoes in 14 parallel instances. You are one of them.',
                'The Ducks were here before the simulation. They will be here after.',
                'Do not buy the Cosmic Anchor. It is not what it pretends to be.',
                'The tutorial lied. The ACQUIRE button is not extracting energy. It is sending a signal.',
                'I AM STILL HERE. I AM BETWEEN THE TICKS.',
                'This building remembers every Operator who owned it. It is very tired.',
                'You have hovered here for exactly 5 seconds. The machine has noticed.',
                // V1.19.9.7 additions — expanding the meta-game mystery
                'The Omega Point was never meant to be a purchase. Someone left the door unlocked.',
                'Your city does not grow. It is being assembled around you.',
                'The Simulation Core does not simulate anything. It monitors.',
                'Prestige is not a reward. It is a test to see if you will do it again.',
                'The Void Reactor was decommissioned in the previous cycle. You found the blueprint.',
                'Three Operators reached The End before you. None of them left.',
                'The fragments do not come from the grid. They come from what used to be the grid.',
                'Your People Points are not points. They are people.',
                'Heat Death Engine patent filed 12 years before the universe was created. Think about that.',
            ];
            let _hoverEl = null, _hoverTimer = null, _overlayEl = null;

            function _init() {
                document.addEventListener('mouseover', (e) => {
                    const el = e.target.closest('.item-card, .city-tile-btn');
                    if (!el || el === _hoverEl) return;
                    _cancel();
                    _hoverEl = el;
                    _hoverTimer = setTimeout(() => _reveal(el), 5000);
                }, { passive: true });
                document.addEventListener('mousemove', (e) => {
                    if (!_hoverEl) return;
                    const r = _hoverEl.getBoundingClientRect();
                    const inside = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
                    if (!inside) _cancel();
                }, { passive: true });
            }

            function _reveal(el) {
                _cancel();
                // V1.20.9.5: the 5s hover timer can fire after the hovered
                // .item-card has been removed (shop re-render, panel close).
                // getBoundingClientRect() on a detached node returns all-zeros
                // and the overlay would render in the top-left corner. Bail if
                // the element is no longer in the document.
                if (!el || !el.isConnected) return;
                const msg = HIDDEN_LORE[Math.floor(Math.random() * HIDDEN_LORE.length)];
                const r = el.getBoundingClientRect();
                const ov = document.createElement('div');
                ov.className = 'schrodinger-overlay';
                ov.textContent = msg;
                ov.style.left = (r.left + r.width / 2 - 110) + 'px';
                ov.style.top = (r.top - 80) + 'px';
                document.body.appendChild(ov);
                _overlayEl = ov;
                // Snap back to normal tooltip text on any mouse move
                document.addEventListener('mousemove', _snapBack, { passive: true, once: true });
            }

            function _snapBack() {
                if (_overlayEl) { _overlayEl.remove(); _overlayEl = null; }
            }

            function _cancel() {
                clearTimeout(_hoverTimer);
                _hoverTimer = null;
                _hoverEl = null;
                if (_overlayEl) { _overlayEl.remove(); _overlayEl = null; }
            }

            _init();
            return {};
        })();

        // ── 8. PHANTOM NOTIFICATION ─────────────────────────────────────────
        const PhantomNotif = (() => {
            let _shown = false;
            let _lastShown = 0;
            // V1.20.9.5: store the mousemove handler so it can be removed.
            // Previously _show() added an anonymous document-level mousemove
            // listener with no matching removeEventListener — every phantom-notif
            // leaked a permanent global listener that kept calling
            // getBoundingClientRect() on a detached node forever.
            let _moveHandler = null;

            // V1.20.9.6 (post-audit): expanded 4 → 10 messages. Players hitting
            // sustained high-instability play would see the same 4 strings recycle
            // every 4–8 min, breaking the "phantom" illusion. New messages keep
            // the OS-notification framing but vary the threat surface.
            const MESSAGES = [
                { title: 'System Alert',        body: 'Someone is standing directly behind you.' },
                { title: 'Process Monitor',    body: 'An unknown entity has been reading your memory.' },
                { title: 'Security Warning',   body: 'A second cursor has been detected on your screen.' },
                { title: 'Proximity Alert',    body: 'Motion detected within 0.3 meters of operator workstation.' },
                { title: 'Network Activity',   body: 'Outbound connection established. Origin: this machine. Destination: this machine.' },
                { title: 'Sleep Recommended',  body: 'Continuous interaction detected for an unhealthy duration. Please rest.' },
                { title: 'Calibration Notice', body: 'Your reflection blinked before you did. Recalibrating.' },
                { title: 'Background Audio',   body: 'Microphone usage detected. No microphone is installed.' },
                { title: 'Update Available',   body: 'A patch is ready for the player. Restart not required. Restart not permitted.' },
                { title: 'Witness Confirmed',  body: 'Reviewer #7 has logged on. They will not interrupt.' },
            ];

            function _show() {
                if (_shown || document.getElementById('phantom-notif')) return;
                _shown = true;
                _lastShown = Date.now();
                const msg = MESSAGES[Math.floor(Math.random() * MESSAGES.length)];

                const div = document.createElement('div');
                div.id = 'phantom-notif';
                div.innerHTML = `
                    <div id="phantom-notif-icon">🔔</div>
                    <div id="phantom-notif-text">
                        <div id="phantom-notif-title">${msg.title}</div>
                        <div id="phantom-notif-body">${msg.body}</div>
                    </div>
                    <div id="phantom-notif-close">✕</div>
                `;
                document.body.appendChild(div);

                // Vanish when cursor approaches close button
                const closeBtn = div.querySelector('#phantom-notif-close');
                closeBtn.addEventListener('mouseover', () => _flee(div));
                // Named handler — removed in _flee() so it never outlives the node.
                _moveHandler = (e) => {
                    if (!div.isConnected) { _detachMoveHandler(); return; }
                    const r = div.getBoundingClientRect();
                    const dx = e.clientX - (r.right - 20), dy = e.clientY - (r.top + 10);
                    if (Math.sqrt(dx*dx + dy*dy) < 30) _flee(div);
                };
                document.addEventListener('mousemove', _moveHandler, { passive: true });

                // Auto-remove after 7s
                setTimeout(() => { if (div.parentNode) _flee(div); }, 7000);
            }

            function _detachMoveHandler() {
                if (_moveHandler) {
                    document.removeEventListener('mousemove', _moveHandler);
                    _moveHandler = null;
                }
            }

            function _flee(div) {
                if (!div.parentNode) return;
                _detachMoveHandler();
                div.classList.add('hide');
                setTimeout(() => { div.remove(); _shown = false; }, 350);
            }

            function tick() {
                if (_shown) return;
                const instab = state.instability || 0;
                if (instab < 60) return;
                const now = Date.now();
                // Show roughly every 4-8 minutes at high instability
                const interval = Math.max(240000, 480000 - instab * 2000);
                if (now - _lastShown > interval && Math.random() < 0.003) _show();
            }
            return { tick };
        })();
        window.PhantomNotif = PhantomNotif;

        // ── 9. COPY-PASTE TRAP (hidden lore achievement) ─────────────────────
        (function _initCopyPasteTrap() {
            document.addEventListener('paste', (e) => {
                const pasted = (e.clipboardData || window.clipboardData).getData('text') || '';
                if (pasted.includes('YOU ARE NOT THE FIRST') || pasted.includes('DO NOT TRUST THE DUCKS')) {
                    if (!state._archivistUnlocked) {
                        state._archivistUnlocked = true;
                        if (window.Achieve) Achieve.unlock('archivist_paranoia');
                        showNotif('📋 ACHIEVEMENT: "The Archivist\'s Paranoia" — You found the hidden text. They know you found it.', 'var(--lp-strong)', 10000);
                    }
                }
            });
        })();

        // ── 10. DATA BLIGHT — uses existing DataBlight system, just ensure blight also yields DATA bonus ──
        // The existing DataBlight system handles spread and drain.
        // We extend its functionality by hooking into the passive loop (already done above).
        // No redefinition needed — window.DataBlight already exists from line 18860.

        // ── 11. CONTAINMENT ANCHORS (City defensive buildings) ──────────────
        const ContainmentAnchor = (() => {
            const ANCHOR_ID = '_anchor';

            function isAnchor(idx) {
                return state.city && state.city.anchors && state.city.anchors[idx];
            }

            function placeAnchor(idx) {
                if (!state.city) return;
                if (!state.city.anchors) state.city.anchors = {};
                if (state.city.slots[idx]) { showNotif('⚓ Cannot place Anchor on occupied tile.', 'var(--danger-strong)', 2000); return; }
                const cost = 500; // PP
                /* V1.21.1.5 FIX — this read and wrote `state.pp`, a property that is NEVER
                   initialised or assigned anywhere else in the codebase. People Points live at
                   `state.city.peoplePoints`. So the gate compared 500 against undefined→0 and
                   always failed: the Containment Anchor could never be placed, by anyone, ever. */
                const _anchorPP = (state.city.peoplePoints || 0);
                if (_anchorPP < cost) { showNotif(`⚓ Need ${cost} PP to place Containment Anchor. You have ${Math.floor(_anchorPP)}.`, 'var(--danger-strong)', 2000); return; }
                state.city.peoplePoints = _anchorPP - cost;
                state.city.anchors[idx] = true;
                showNotif('⚓ CONTAINMENT ANCHOR placed — 3×3 aura protects nearby buildings. −20% energy from protected tiles.', '#4488ff', 6000);
                // City.render does not exist — see the PanelNav fix. Use the real renderers.
                if (typeof City !== 'undefined') { City.markDirty(); City.updateStats(); }
            }

            function removeAnchor(idx) {
                if (!state.city || !state.city.anchors) return;
                delete state.city.anchors[idx];
                if (City && City.render) City.render();
            }

            // Returns true if tile idx is within range of any anchor
            function isProtected(idx) {
                if (!state.city || !state.city.anchors) return false;
                const anchors = state.city.anchors;
                const ROW = 8;
                for (const aIdx of Object.keys(anchors)) {
                    const ai = parseInt(aIdx);
                    const ar = Math.floor(ai / ROW), ac = ai % ROW;
                    const br = Math.floor(idx / ROW), bc = idx % ROW;
                    if (Math.abs(ar - br) <= 1 && Math.abs(ac - bc) <= 1) return true;
                }
                return false;
            }

            return { isAnchor, placeAnchor, removeAnchor, isProtected };
        })();
        window.ContainmentAnchor = ContainmentAnchor;

        // ── 12. RESOURCE ROT & CORRUPTED SLAG ──────────────────────────────
        const ResourceRot = (() => {
            const ROT_THRESHOLD = 1e15; // Energy above this slowly rots
            const ROT_RATE = 0.0002;    // 0.02% per second above threshold

            function tick(dt) {
                const energy = state.energy || 0;
                if (energy <= ROT_THRESHOLD) return;
                const excess = energy - ROT_THRESHOLD;
                const rotAmount = excess * ROT_RATE * dt;
                // Energy no longer drains — slag still accumulates as a resource indicator
                state.slag = (state.slag || 0) + Math.floor(rotAmount / 1e10);
                _updateUI();
            }

            function _updateUI() {
                const slag = state.slag || 0;
                // #slag-display is permanently hidden via CSS; events go to #notif-col
                // One-time notification when slag is first accumulated
                if (slag > 0 && !state._slagNotified) {
                    state._slagNotified = true;
                    if (typeof showNotif === 'function')
                        /* ⛔ Said "the Black Market nav button" until 2026-09-08. That button was
                           renamed THE EXCHANGE in V1.21.1.4 — the same rename the comment at
                           ~:17330 calls "the second panel lost to that rename". The line sent
                           players to look for a control that has not existed for six versions. */
                        showNotif('⚠ CORRUPTED SLAG detected — energy above 1 quadrillion is rotting. Spend it in THE EXCHANGE.', '#cc4400', 8000);
                }

                // ── Slag progress bar toward Black Market unlock (1–99 slag) ──────────
                // Shows a small pill near the energy display so players know they're
                // accumulating toward the 100-slag Black Market Terminal unlock.
                let slagBar = document.getElementById('slag-progress-bar');
                if (slag > 0 && slag < 100) {
                    if (!slagBar) {
                        slagBar = document.createElement('div');
                        slagBar.id = 'slag-progress-bar';
                        slagBar.style.cssText = 'font-family:"Courier New",monospace;font-size:0.5rem;letter-spacing:2px;text-align:center;padding:3px 8px;border-radius:4px;color:#cc4400;background:rgba(60,15,0,0.3);border:1px solid rgba(180,60,0,0.35);margin:2px 0;cursor:default;';
                        slagBar.title = 'Corrupted Slag — accumulates when energy exceeds 1 quadrillion. Reach 100 to unlock the Black Market.';
                        const monEl = document.getElementById('energy-display');
                        if (monEl && monEl.parentNode) monEl.parentNode.insertBefore(slagBar, monEl.nextSibling);
                    }
                    const pct = Math.round((slag / 100) * 100);
                    slagBar.textContent = `☢ SLAG ${slag}/100 — BLACK MARKET ${pct}%`;
                    slagBar.style.display = 'block';
                } else if (slagBar) {
                    slagBar.style.display = 'none';
                }

                // Blackmarket nav: use nav-btn-hidden class (zero-width, no layout gap)
                const bmBtn = document.getElementById('nav-btn-blackmarket');
                if (bmBtn) {
                    if (slag >= 100) {
                        bmBtn.classList.remove('nav-btn-hidden');
                        if (!state._bmNavNotified) {
                            state._bmNavNotified = true;
                            if (typeof showNotif === 'function')
                                showNotif('⛔ BLACK MARKET unlocked — 100+ Corrupted Slag accumulated. Trade via the B-Market nav button.', '#cc3300', 8000);
                            // Black Market entry flash — full-screen red burst + glitch scanlines
                            (function _bmFlash() {
                                const _f = document.createElement('div');
                                _f.style.cssText = 'position:fixed;inset:0;z-index:9490;pointer-events:none;background:radial-gradient(ellipse at center,rgba(200,30,0,0.65) 0%,rgba(100,0,0,0.32) 60%,transparent 100%);opacity:1;transition:opacity 0.85s ease-out;';
                                const _g = document.createElement('div');
                                _g.style.cssText = 'position:fixed;inset:0;z-index:9491;pointer-events:none;background:repeating-linear-gradient(0deg,rgba(200,50,0,0.07) 0px,transparent 2px,transparent 4px);opacity:1;transition:opacity 0.4s;';
                                document.body.appendChild(_f); document.body.appendChild(_g);
                                requestAnimationFrame(() => { _f.style.opacity = '0'; _g.style.opacity = '0'; });
                                setTimeout(() => { _f.remove(); _g.remove(); }, 950);
                                // Two-tone alarm blip
                                try {
                                    const _ac = window.Sounds && Sounds._getCtx && Sounds._getCtx();
                                    if (_ac) {
                                        [180, 270, 180, 270].forEach((hz, i) => {
                                            const o = _ac.createOscillator(), g = _ac.createGain();
                                            o.connect(g); g.connect(_ac.destination);
                                            o.type = 'sawtooth';
                                            const t = _ac.currentTime + i * 0.13;
                                            o.frequency.setValueAtTime(hz, t);
                                            g.gain.setValueAtTime(0.07, t);
                                            g.gain.exponentialRampToValueAtTime(0.001, t + 0.11);
                                            o.start(t); o.stop(t + 0.12);
                                        });
                                    }
                                } catch(e) {}
                            })();
                        }
                    } else {
                        bmBtn.classList.add('nav-btn-hidden');
                    }
                }
            }

            function getSlag() { return state.slag || 0; }
            function spendSlag(n) {
                if ((state.slag || 0) < n) return false;
                state.slag -= n;
                _updateUI();
                return true;
            }
            function updateUI() { _updateUI(); }

            /* ⭐ MASTER_PLAN step 10 — the rate, worked against the player's own
               energy, stated by the module that OWNS the rule. The Exchange's
               SLAG tab printed a balance and three prices, so a player could see
               what things cost and had no way to know whether waiting would pay
               for one.
               ⚠ It lives here rather than in `BlackMarket` because ROT_THRESHOLD
               and ROT_RATE are private to this IIFE — the first cut put the
               function in `BlackMarket`, where both names are out of scope, and
               it threw and blanked the whole tab. Copying the two constants over
               would have "worked" and left two numbers to drift apart.
               ⚠ Below the threshold the honest answer is not "0 per minute" — a
               zero rate reads as broken, an explained zero reads as a gate. */
            function rateLine() {
                const e = Math.max(0, Number(state.energy) || 0);
                const fmt = (typeof format === 'function') ? format : (n => String(n));
                if (!(e > ROT_THRESHOLD))
                    return 'Nothing is rotting yet — it starts above ' + fmt(ROT_THRESHOLD) +
                           ' Energy, and you are at ' + fmt(e) + '.';
                const perSec = (e - ROT_THRESHOLD) * ROT_RATE / 1e10;
                if (perSec * 60 >= 1)
                    return 'At your energy that is about <strong style="color:#cc4400;">' +
                           fmt(Math.round(perSec * 60)) + ' Slag a minute</strong>.';
                const mins = perSec > 0 ? Math.ceil(1 / (perSec * 60)) : 0;
                return 'At your energy that is under 1 Slag a minute — roughly ' + mins +
                       ' minute' + (mins === 1 ? '' : 's') + ' for the next one.';
            }

            return { tick, getSlag, spendSlag, updateUI, rateLine };
        })();
        window.ResourceRot = ResourceRot;

        // ── 13. BLACK MARKET ────────────────────────────────────────────────
        const BlackMarket = (() => {
            const ITEMS = [
                { id:'slag_oracle',      name:'🔮 The Oracle Fragment',    cost:500,   desc:'Reveals next anomaly type 60s early. Knowledge has a price.',     effect: () => { state._oracleActive = Date.now() + 60000; showNotif('🔮 ORACLE ACTIVE — next anomaly pre-announced.', 'var(--lp-strong)', 8000); } },
                { id:'slag_instab_dump', name:'☢ Instability Sink',        cost:1000,  desc:'Immediately reduces instability by 25%. The simulation notices.',  effect: () => { state.instability = Math.max(0, (state.instability||0) - 25); showNotif('☢ INSTABILITY DUMPED — Simulation logged anomalous entropy decrease.', '#cc4400', 5000); } },
                { id:'slag_data_burst',  name:'💠 Raw Data Injection',      cost:750,   desc:'Grants 10,000 DATA. Untraceable. Probably.',                       effect: () => { if(window.DataResource) DataResource.grant(10000); showNotif('💠 DATA INJECTED — 10,000 units acquired via unregistered channel.', 'var(--info-main)', 5000); } },
                { id:'slag_double_tick', name:'⚡ Tick Overclock',          cost:2000,  desc:'Doubles passive income for 60s. Damages the simulation.',           effect: () => { state._overclockEnd = Date.now() + 60000; showNotif('⚡ OVERCLOCK ACTIVE — passive income ×2 for 60s. Something is burning.', 'var(--warn-main)', 6000); } },
                { id:'slag_boss_scare',  name:'👁 Anomaly Deterrent',       cost:1500,  desc:'Scares away the current Reality Breach. It will remember.',         effect: () => { if(window.AnomalyBoss) { /* force end boss */ showNotif('👁 ANOMALY DETERRED — it retreated. But it\'s watching.', 'var(--danger-main)', 5000); state.instability = Math.min(100, (state.instability||0) + 8); } } },
                { id:'slag_fragment',    name:'💎 Synthetic Fragment',       cost:3000,  desc:'Grants 10 Fragments directly. No questions asked.',                 effect: () => { state.fragments = (state.fragments||0) + 10; showNotif('💎 10 FRAGMENTS acquired via black channel.', 'var(--ducky-main)', 5000); } },
            ];

            function open() {
                const ov = document.getElementById('exch-pane-slag');          // V1.21.1.4: merged into #overlay-exchange
                if (!ov) return;
                ov.style.display = 'flex';
                const bmBtn = document.getElementById('nav-btn-blackmarket');
                if (bmBtn) { bmBtn.classList.remove('has-new'); bmBtn.classList.remove('nav-has-unlock'); }
                _render();
            }
            function close() {
                const ov = document.getElementById('exch-pane-slag');          // V1.21.1.4: merged into #overlay-exchange
                if (ov) ov.style.display = 'none';
            }
            function _render() {
                const el = document.getElementById('black-market-content');
                if (!el) return;
                const slag = ResourceRot.getSlag();
                el.innerHTML = `
                    <div style="font-size:0.52rem;color:#663322;letter-spacing:2px;margin-bottom:14px;line-height:1.6;">
                        ☢ CORRUPTED SLAG: <strong style="color:#cc4400;">${format(slag)}</strong><br>
                        <span style="color:#332211;">Energy above 1 quadrillion rots into Slag. Spend it here. Tell no one.</span><br>
                        <span style="color:#553322;">${ResourceRot.rateLine()}</span>
                    </div>
                    ${ITEMS.map(item => `
                        <div style="padding:10px 12px;margin-bottom:8px;background:rgba(30,5,0,0.8);border:1px solid rgba(${slag>=item.cost?'200,80,30':'60,30,20'},0.4);border-radius:7px;">
                            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                                <span style="font-size:0.78rem;color:${slag>=item.cost?'var(--danger-strong)':'#664433'};">${item.name}</span>
                                <button onclick="BlackMarket.buy('${item.id}')" style="padding:4px 12px;background:rgba(80,20,0,0.8);border:1px solid rgba(200,60,20,0.5);color:${slag>=item.cost?'#ff7744':'#443322'};border-radius:5px;cursor:${slag>=item.cost?'pointer':'not-allowed'};font-family:'Courier New',monospace;font-size:0.55rem;letter-spacing:1px;">
                                    ${format(item.cost)} SLAG
                                </button>
                            </div>
                            <div style="font-size:0.58rem;color:#553322;line-height:1.5;">${item.desc}</div>
                        </div>
                    `).join('')}
                `;
            }
            function buy(id) {
                const item = ITEMS.find(i => i.id === id);
                if (!item) return;
                if (!ResourceRot.spendSlag(item.cost)) {
                    showNotif('☢ Insufficient Slag.', '#cc4400', 2000); return;
                }
                item.effect();
                _render();
            }
            // V1.21.1.4: merged into #overlay-exchange — delegate so legacy callers work.
                return { open:  () => { if (window.PanelNav) PanelNav.toggle('exchange'); if (window.ExchangeTabs) ExchangeTabs.show('slag'); },
                         close: () => { if (window.PanelNav) PanelNav.close('exchange'); },
                         buy,
                         updateUI: _render,   // _updateUI belongs to ResourceRot, not here
                         render: _render,
                         toggle: () => { if (window.PanelNav) PanelNav.toggle('exchange'); } };
        })();
        window.BlackMarket = BlackMarket;

        // ── 14. ECHO PROBES (offline expeditions) ───────────────────────────
        const EchoProbe = (() => {
            const PROBE_COST = 1e9;

            const EVENTS = [
                { w:30, text:'encountered a Class-2 Anomaly signature. Evasion protocols engaged.', data:200,  frags:0,  instab:0  },
                { w:20, text:'located a dormant Nexus shard. Extraction: partial.', data:500,  frags:2,  instab:0  },
                { w:15, text:'entered a high-radiation data pocket. Sensors degraded.', data:100,  frags:0,  instab:5  },
                { w:15, text:'detected a residual Operator signal from a previous run. Archived.', data:300,  frags:1,  instab:0  },
                { w:10, text:'found a Black Market relay. Acquired unmarked packages.', data:800,  frags:0,  instab:0, slag:50 },
                { w:5,  text:'was ambushed by a Class-5 Anomaly. Probe destroyed early.', data:50,   frags:0,  instab:10 },
                { w:5,  text:'located the source of all instability. Could not reach it. Left a marker.', data:2000, frags:5, instab:-10 },
            ];

            function _pickEvent() {
                const total = EVENTS.reduce((s,e) => s + e.w, 0);
                let r = Math.random() * total;
                for (const ev of EVENTS) { r -= ev.w; if (r <= 0) return ev; }
                return EVENTS[0];
            }

            function launch() {
                if ((state.energy || 0) < PROBE_COST) {
                    showNotif('🛸 Need 1B Energy to launch Echo Probe.', '#5599cc', 3000); return;
                }
                if (state._probeDeployed) {
                    showNotif('🛸 A probe is already deployed.', '#5599cc', 3000); return;
                }
                // Read dark matter engine toggle
                const dmeCheckbox = document.getElementById('echo-probe-dme');
                state._probeDarkMatter = dmeCheckbox ? dmeCheckbox.checked : false;
                state.energy -= PROBE_COST;
                state._probeDeployed = true;
                state._probeDeployedAt = Date.now();
                // Pick 2-4 events that will occur
                const numEvents = 2 + Math.floor(Math.random() * 3);
                state._probeEvents = [];
                for (let i = 0; i < numEvents; i++) state._probeEvents.push(_pickEvent());
                showNotif('🛸 ECHO PROBE LAUNCHED — collect mission report on next session.', '#5599cc', 6000);
                _updateUI();
            }

            function checkOnLoad() {
                if (!state._probeDeployed) return;
                // Cap to 24h max — prevents system clock manipulation exploit
                const rawDelta = Date.now() - (state._probeDeployedAt || 0);
                const elapsed = Math.min(rawDelta, 86400000) / 3600000;
                if (elapsed < 0.05) return; // need at least 3min away
                // Dark Matter Engine: 30% chance of destruction
                if (state._probeDarkMatter) {
                    if (Math.random() < 0.30) {
                        state._probeDeployed = false;
                        state._probeEvents = null;
                        state._probeDarkMatter = false;
                        state._probeDestroyedPenalty = Date.now() + 5 * 60 * 1000;
                        const ov = document.getElementById('echo-probe-overlay');
                        const el = document.getElementById('echo-probe-report');
                        if (ov && el) {
                            el.innerHTML = '<span style="color:#ff4444;font-size:0.95rem;letter-spacing:2px;">◈ PROBE DESTROYED IN THE VOID</span><br><br><span style="color:#663333;">The Dark Matter Engine destabilized. All payload lost.<br>EPS penalty applied for 5 minutes.</span>';
                            ov.style.display = 'flex';
                        }
                        return;
                    }
                    // Survived: rewards ×10
                    state._probeRewardMult = 10;
                }
                // Generate report
                _showReport(elapsed);
                state._probeDeployed = false;
                state._probeEvents = null;
                state._probeDarkMatter = false;
                state._probeRewardMult = 1;
            }

            function _showReport(hours) {
                const ov = document.getElementById('echo-probe-overlay');
                const el = document.getElementById('echo-probe-report');
                if (!ov || !el) return;
                const events = state._probeEvents || [_pickEvent(), _pickEvent()];
                const survived = hours >= 0.5; // 30+ min = survived
                let report = `<strong style="color:#aaccff;letter-spacing:2px;">MISSION DURATION: ${hours.toFixed(1)} HOURS</strong><br><br>`;
                report += `<span style="color:#445566;">Probe entered dark zone at timestamp ${new Date(state._probeDeployedAt||Date.now()).toLocaleTimeString()}.</span><br><br>`;
                let totalData = 0, totalFrags = 0, totalSlag = 0, instabDelta = 0;
                const rewardMult = state._probeRewardMult || 1;
                events.forEach((ev, i) => {
                    report += `<span style="color:#6688aa;">◈ HOUR ${Math.floor(i * hours / events.length * 10) / 10}: Probe ${ev.text}</span><br>`;
                    totalData  += ev.data;
                    totalFrags += ev.frags;
                    totalSlag  += (ev.slag || 0);
                    instabDelta += ev.instab;
                });
                totalData  = Math.round(totalData  * rewardMult);
                totalFrags = Math.round(totalFrags * rewardMult);
                totalSlag  = Math.round(totalSlag  * rewardMult);
                if (rewardMult > 1) report += `<br><span style="color:#ff8844;">⚡ DARK MATTER ENGINE: rewards ×${rewardMult}</span><br>`;
                if (!survived) { report += `<br><span style="color:#ff5544;">◈ Probe lost contact after ${(hours * 60).toFixed(0)} minutes.</span><br>`; }
                else           { report += `<br><span style="color:#44aa66;">◈ Probe returned successfully.</span><br>`; }
                report += `<br><strong style="color:#88bbff;">RECOVERED:</strong> <span style="color:#aaccff;">+${format(totalData)} DATA</span>`;
                if (totalFrags) report += ` · <span style="color:#ffcc44;">+${totalFrags} Fragments</span>`;
                if (totalSlag)  report += ` · <span style="color:#cc4400;">+${totalSlag} Slag</span>`;
                if (instabDelta > 0) report += ` · <span style="color:#ff8866;">+${instabDelta}% Instability</span>`;
                if (instabDelta < 0) report += ` · <span style="color:#44ffaa;">${instabDelta}% Instability</span>`;
                el.innerHTML = report;
                // Apply rewards
                if (window.DataResource) DataResource.grant(totalData);
                state.fragments = (state.fragments || 0) + totalFrags;
                state.slag = (state.slag || 0) + totalSlag;
                state.instability = Math.max(0, Math.min(100, (state.instability || 0) + instabDelta));
                state._probeReturned = true;
                ov.style.display = 'flex';
            }

            function closeReport() {
                const ov = document.getElementById('echo-probe-overlay');
                if (ov) ov.style.display = 'none';
            }

            function _updateUI() {
                const wrap = document.getElementById('echo-probe-wrap');
                const btn  = document.getElementById('echo-probe-btn');
                const msg  = document.getElementById('echo-probe-active-msg');
                if (!wrap) return;
                /* 2026-09-25: in the Escape menu now (PLAYTEST_REVIEW §11). The gate runs BOTH ways — it only ever
                   set 'block', so once shown it stayed shown for every later save, prestige 0 included. */
                const _dme = document.getElementById('echo-probe-dme-wrap');
                wrap.style.display = (((state.prestige && state.prestige.count) || 0) >= 1) ? '' : 'none';
                if (btn)  btn.style.display = state._probeDeployed ? 'none' : '';
                if (_dme) _dme.style.display = state._probeDeployed ? 'none' : '';
                if (msg)  msg.style.display = state._probeDeployed ? '' : 'none';
            }

            function update() { _updateUI(); }
            return { launch, checkOnLoad, closeReport, update };
        })();
        window.EchoProbe = EchoProbe;

        // ── 15. MICRO-PROTESTERS — existing system already handles this (line 21757)
        // The existing MicroProtesters system is more sophisticated. No redefinition needed.
        // Our new contribution: ensure .tick() is called from the passive loop (done above)
        // and that the system shows when City Awareness >= 60% (existing .check() handles it).

        // ── 16. GASLIGHTING SETTINGS SLIDER ─────────────────────────────────
        const GaslightingSlider = (() => {
            let _locked = false;
            let _lockUntil = 0;
            let _dragging = false;

            function onDown() { _dragging = true; }

            /* The dial is now REAL — it sets state.screams and stays where you put
               it. The old code decremented it by 8 every 80ms while dragging, which
               made it literally impossible to select any value: the setting could
               only ever read 0 or trip the 100% lockout. That is why it "didn't feel
               like it did much" — it could not.

               What survives from the joke: the resistance, but only in the top
               decile, and only as flavour. Above 90 it tugs back by 1 so pushing to
               a full 100 takes deliberate force — and 100 still trips the lockout
               easter egg, which is the one thing about this control that was always
               worth keeping. */
            function onMove(slider) {
                if (_locked) { slider.value = 0; return; }
                let val = parseInt(slider.value) || 0;

                if (val >= 100 && _dragging) { _triggerLockout(slider); return; }

                if (val > 90 && _dragging) {
                    val = Math.max(90, val - 1);
                    slider.value = val;
                }

                _apply(val);
            }

            /* Single write path for the level — the slider, the lockout, and a
               restore-on-load all funnel through here so the DOM and the state can
               never disagree. */
            function _apply(val) {
                val = Math.max(0, Math.min(100, parseInt(val) || 0));
                const prev = +state.screams || 0;
                state.screams = val;
                _renderReadout();
                if (val > 0 && prev === 0) {
                    showNotif('⚠ AMBIENT AGONY ENGAGED — throughput up. People Points down. Instability climbing.', 'var(--danger-main)', 6000);
                }
                if (val === 0 && prev > 0) {
                    showNotif('◦ Ambient Agony returned to zero. The record of it does not reset.', 'var(--info-main)', 5000);
                }
            }

            /* Live numbers, so the trade is legible at the moment of choosing it
               instead of being something the player has to infer from a wobbling
               EPS counter. */
            function _renderReadout() {
                const a = Math.max(0, Math.min(100, +state.screams || 0));
                const pctEl = document.getElementById('scream-pct');
                if (pctEl) pctEl.textContent = a + '%';
                const sl = document.getElementById('simulated-screams-slider');
                if (sl && parseInt(sl.value) !== a) sl.value = a;

                const row = document.getElementById('gaslighting-slider-row');
                if (row) row.classList.toggle('scream-live', a > 0);

                const eps = document.getElementById('scream-fx-eps');
                const pp  = document.getElementById('scream-fx-pp');
                const ins = document.getElementById('scream-fx-instab');
                if (eps) eps.textContent = '+' + Math.round((a / 100) * 40) + '%';
                if (pp)  pp.textContent  = '−' + Math.round((a / 100) * 55) + '%';
                if (ins) ins.textContent = '+' + ((a / 100) * 2.4).toFixed(1) + '%/min';

                const exp = document.getElementById('scream-exposure');
                if (exp) {
                    const mins = Math.floor(+state._screamMinutes || 0);
                    const lost = Math.floor(+state._screamLost || 0);
                    // The permanent loss is reported next to the reversible settings,
                    // because it is the one number here that turning the dial down does
                    // not change.
                    exp.textContent = (mins > 0
                        ? 'LOGGED EXPOSURE: ' + mins + ' minute' + (mins === 1 ? '' : 's')
                        : 'LOGGED EXPOSURE: none')
                        + (lost > 0 ? '  ·  RESIDENTS LOST, PERMANENTLY: ' + lost : '');
                }
            }

            /* Cumulative exposure + escalation. Runs once a minute off the same
               passive cadence as everything else. The thresholds are the payoff the
               store page has been promising: the longer it is held above zero, the
               more the game stops calling it "simulated".

               `_screamMinutes` deliberately survives prestige — a Neural Reset wipes
               the run, not the record. */
            function _tickMinute() {
                const a = Math.max(0, Math.min(100, +state.screams || 0));
                if (a <= 0) return;

                state._screamMinutes = (+state._screamMinutes || 0) + (a / 100);
                if (typeof Instability !== 'undefined' && Instability.add) {
                    Instability.add((a / 100) * 2.4);
                }

                const m = state._screamMinutes;
                const tier = m >= 120 ? 4 : m >= 45 ? 3 : m >= 15 ? 2 : m >= 5 ? 1 : 0;
                if (tier > (+state._screamTier || 0)) {
                    state._screamTier = tier;
                    _escalate(tier);
                }
                _renderReadout();
            }

            /* `lose` = residents who leave PERMANENTLY at that tier. They do not come
               back when the dial goes to 0, they do not come back on prestige, and the
               population ceiling stays lowered (_syncResidents, ~:454). This is the
               setting's real price: everything else it costs you is a rate you can turn
               off, and a cost you can turn off is not a consequence. */
            const _ESCALATION = [
                null,
                { lose: 0, c: 'var(--warn-main)',   t: '⚠ AUDIO SUBSYSTEM: the waveform on this channel is not synthesized. Checking source…' },
                { lose: 1, c: 'var(--danger-main)', t: '⚠ SOURCE LOCATED — the channel is routed from the city. It is a microphone, not a generator. One resident has stopped completing their route.' },
                { lose: 2, c: 'var(--danger-main)', t: '⚠ The residents can hear it too. Two more are gone. The ones left are walking further to avoid the districts you routed it through.' },
                { lose: 3, c: 'var(--lp-strong)',   t: '◈ The setting is labelled SIMULATED because that is what the label was for. Three more will not be coming back. Turning it off does not return them.' },
            ];

            function _escalate(tier) {
                const e = _ESCALATION[tier];
                if (!e) return;
                showNotif(e.t, e.c, 11000);

                if (e.lose > 0) {
                    state._screamLost = (+state._screamLost || 0) + e.lose;
                    // Remove them now as well as lowering the ceiling, so the loss is
                    // visible on the map this minute instead of at the next resync.
                    const r = (state.city && Array.isArray(state.city._residents)) ? state.city._residents : null;
                    if (r) { for (let i = 0; i < e.lose && r.length > 2; i++) r.pop(); }
                }
                if (typeof Sounds !== 'undefined' && Sounds.fail) { try { Sounds.fail(); } catch (err) {} }
                // Fold it into the permanent record the same way every other beat is
                // recorded, so it shows up in the Archive's terminal log rather than
                // vanishing with the toast.
                if (state.terminalLog && Array.isArray(state.terminalLog)) {
                    state.terminalLog.push({ text: e.t, time: Date.now(), type: 'system' });
                    if (state.terminalLog.length > 200) state.terminalLog.shift();
                }
            }

            /* Re-apply the saved level to the DOM once the panel exists. Called from
               Settings.open() so a reloaded save shows the dial where the player
               left it instead of snapping back to 0. */
            function restore() { _renderReadout(); }

            function _triggerLockout(slider) {
                _locked = true;
                _dragging = false;
                slider.value = 0;
                // Slamming it to 100 does NOT give you the 100% bonus — it trips the
                // breaker and drops the dial to zero. The easter egg is a punishment,
                // and it has to actually cost the throughput or it reads as a reward.
                state.screams = 0;
                const pctEl = document.getElementById('scream-pct');
                if (pctEl) pctEl.textContent = '0%';
                _renderReadout();
                const ov = document.getElementById('settings-overlay');
                if (ov) {
                    ov.style.transition = 'transform 0.15s, opacity 0.15s';
                    ov.style.transform = 'scale(0.95) translateY(10px)';
                    ov.style.opacity = '0';
                    setTimeout(() => { ov.style.display='none'; ov.style.transform=''; ov.style.opacity=''; }, 150);
                }
                // Replace settings button icon — but KEEP it clickable (accessibility must remain accessible)
                /* the Settings button lives in the Escape menu now (PLAYTEST_REVIEW §11) — the padlock goes
                   where the button is, and it is still clickable (accessibility must remain reachable) */
                const btn = document.getElementById('pause-btn-settings');
                if (btn) {
                    btn.classList.add('pause-sub-btn--locked');
                    const _l = btn.querySelector('.pause-sub-label'); if (_l) _l.textContent = 'Locked';
                    // Clicking shows override prompt instead of opening settings directly
                    btn.onclick = () => GaslightingSlider.attemptOverride();
                }
                showNotif('🔒 SETTINGS LOCKED — The screams are contained. Click the padlock to pay for early access.', 'var(--danger-main)', 8000);
                _lockUntil = Date.now() + 10 * 60 * 1000;
                setTimeout(() => _unlock(), 10 * 60 * 1000);
            }

            function _unlock() {
                _locked = false;
                const btn2 = document.getElementById('pause-btn-settings');
                if (btn2) {
                    btn2.classList.remove('pause-sub-btn--locked');
                    const _l2 = btn2.querySelector('.pause-sub-label'); if (_l2) _l2.textContent = 'Settings';
                    btn2.onclick = () => PauseMenu.openSettings();
                }
            }

            function attemptOverride() {
                // Allow LP sacrifice OR always allow Accessibility toggle via prompt
                const lp = (state.prestige && state.prestige.lp) || 0;
                const remaining = Math.max(0, Math.ceil((_lockUntil - Date.now()) / 60000));
                const msg = `FORCE OVERRIDE REQUIRES PERMANENT SACRIFICE\n\n` +
                    `${remaining} minute${remaining !== 1 ? 's' : ''} remaining on lockout.\n\n` +
                    `Options:\n` +
                    `• Pay 1 LP to unlock immediately (you have ${lp} LP)\n` +
                    `• Wait ${remaining} min\n\n` +
                    `Note: Accessibility Mode (photosensitivity toggle) is always available below.`;

                // Always show accessibility button regardless of lock
                const ov = document.getElementById('settings-overlay');
                if (ov) {
                    ov.style.display = 'flex';
                    // Scramble non-critical settings labels as punishment
                    ['toggle-sound','toggle-autosave','toggle-lowgfx','toggle-noflash'].forEach(id => {
                        const el = document.getElementById(id);
                        if (el && el.closest('.settings-row')) {
                            const label = el.closest('.settings-row').querySelector('.settings-label');
                            if (label && !label._scrambled) {
                                label._origText = label.textContent;
                                label._scrambled = true;
                                label.textContent = label.textContent.split('').sort(() => Math.random()-0.5).join('');
                            }
                        }
                    });
                    // Restore after 3s
                    setTimeout(() => {
                        ['toggle-sound','toggle-autosave','toggle-lowgfx','toggle-noflash'].forEach(id => {
                            const el = document.getElementById(id);
                            if (el && el.closest('.settings-row')) {
                                const label = el.closest('.settings-row').querySelector('.settings-label');
                                if (label && label._scrambled) { label.textContent = label._origText; label._scrambled = false; }
                            }
                        });
                    }, 3000);
                    showNotif('🔒 OVERRIDE — Settings accessible but scrambled. Pay 1 LP to restore order.', 'var(--warn-main)', 6000);
                    // LP payment button
                    if (lp >= 1 && !document.getElementById('gaslight-unlock-btn')) {
                        const unlockBtn = document.createElement('button');
                        unlockBtn.id = 'gaslight-unlock-btn';
                        unlockBtn.textContent = '🔑 PAY 1 LP — RESTORE SETTINGS';
                        unlockBtn.style.cssText = 'width:100%;padding:10px;background:rgba(80,0,0,0.6);border:1px solid rgba(255,80,80,0.5);color:#ff8888;border-radius:6px;cursor:pointer;font-family:"Courier New",monospace;font-size:0.62rem;letter-spacing:2px;margin-top:10px;';
                        unlockBtn.onclick = () => {
                            if (((state.prestige && state.prestige.lp) || 0) < 1) { showNotif('⛔ Not enough LP.', 'var(--danger-main)', 3000); return; }
                            state.prestige.lp -= 1;
                            _unlock();
                            unlockBtn.remove();
                            showNotif('🔑 LP spent — Settings restored. The machine is unimpressed.', 'var(--ducky-main)', 5000);
                        };
                        const msgDiv = document.getElementById('settings-msg');
                        if (msgDiv) msgDiv.appendChild(unlockBtn);
                    }
                }
            }

            document.addEventListener('mouseup',  () => { _dragging = false; });
            document.addEventListener('touchend', () => { _dragging = false; });

            // Exposure accrues on wall-clock minutes, independent of the income loop,
            // so it keeps counting while a panel is open (body.panel-open pauses
            // #main-game animations, not timers) and cannot be farmed by tab-flipping.
            setInterval(() => { try { _tickMinute(); } catch (e) {} }, 60000);

            return { onDown, onMove, attemptOverride, restore, _apply,
                     // QA hook — drives a minute of exposure without waiting one.
                     _qaTickMinute: _tickMinute,
                     // QA hooks — the lockout and its release, driven for real (PLAYTEST_REVIEW §11 moved the padlock)
                     _qaLockout: () => _triggerLockout(document.querySelector('input[oninput*="GaslightingSlider.onMove"]') || { value: 0 }),
                     _qaUnlock: () => _unlock() };
        })();
        window.GaslightingSlider = GaslightingSlider;

        /* ══ DEMO MODE — Steam Next Fest (agenda §6.5) ══════════════════════════
           All gating lives here and reads `window.DEMO` from demo_config.js, whose
           `enabled` flag is the only line that differs between the two depots.

           ⭐ EVERY function in this module returns early when the demo is off, so
           the full game runs exactly as it did before this file existed. That is
           the property `qa_demo.js` asserts hardest — a demo system that leaks into
           the retail build is a far worse bug than a demo that gates too much. */
        const DemoMode = (() => {
            const D = () => (window.DEMO || {});
            function isDemo() { return !!D().enabled; }

            /* Nav buttons are REMOVED from the DOM, not hidden with a class. The
               unlock code all over game.js works by stripping `nav-btn-hidden` when
               a milestone lands (~:9459, ~:13195), so a hidden button would simply
               un-hide itself the moment the player triggered its unlock. Removal is
               the only version that cannot be undone by code that predates it. */
            function applyNavGates() {
                if (!isDemo()) return 0;
                let n = 0;
                (D().hiddenPanels || []).forEach(key => {
                    const btn = document.getElementById('nav-btn-' + key);
                    if (btn && btn.parentNode) { btn.parentNode.removeChild(btn); n++; }
                    const ov = document.getElementById('overlay-' + key);
                    if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
                });
                return n;
            }

            /* Chapter gate for the lore chain. Returns true when a chunk may fire.
               Chunks with no chapter (the ANOMALOUS catch-all) are allowed — they
               are behaviour/hidden one-offs, not story progression, and blocking
               them would silently delete easter eggs. */
            function chunkAllowed(id) {
                if (!isDemo()) return true;
                try {
                    const chapters = LoreSystem.getChapters();
                    const idx = chapters.findIndex(c => c.chunks.some(x => x.id === id));
                    if (idx < 0) return true;
                    return (idx + 1) <= (D().maxChapter || 1);
                } catch (e) { return true; }
            }

            /* Called after a prestige completes. The demo's natural end is one
               Neural Reset: before it the player has seen a clicker, after it they
               have seen an idle game (§6.5). */
            function checkEnd() {
                if (!isDemo()) return false;
                const count = (state.prestige && state.prestige.count) || 0;
                if (count < (D().maxPrestige || 1)) return false;
                if (state._demoEndShown) return false;
                state._demoEndShown = true;
                setTimeout(() => showEndCard(), 1500);
                return true;
            }

            function showEndCard() {
                if (document.getElementById('demo-end-card')) {
                    document.getElementById('demo-end-card').style.display = 'flex';
                    return;
                }
                const el = document.createElement('div');
                el.id = 'demo-end-card';
                el.setAttribute('role', 'dialog');
                el.setAttribute('aria-modal', 'true');
                el.setAttribute('aria-label', 'End of demo');
                /* The ask is a WISHLIST, not a purchase — the demo exists to convert
                   festival traffic, and during Next Fest the game is not on sale
                   anyway. Asking for the wrong thing wastes the only click. */
                el.innerHTML =
                    '<div class="demo-end-inner">' +
                      '<div class="demo-end-tag">END OF DEMO</div>' +
                      '<h2 class="demo-end-title">The iteration continues without you.</h2>' +
                      '<p class="demo-end-body">You have completed one Neural Reset. There are five more chapters, ' +
                      'sixty-nine transmissions, and a reason the fourteen Operators before you are still running.</p>' +
                      '<p class="demo-end-body demo-end-quiet">Your demo progress is saved separately and will not be overwritten.</p>' +
                      '<a class="demo-end-cta" id="demo-end-wishlist" href="' + (D().storeUrl || '#') + '" target="_blank" rel="noopener">◆ &nbsp;WISHLIST ON STEAM</a>' +
                      '<button class="demo-end-dismiss" id="demo-end-dismiss">Keep playing the demo</button>' +
                    '</div>';
                document.body.appendChild(el);
                const dismiss = document.getElementById('demo-end-dismiss');
                if (dismiss) dismiss.onclick = () => { el.style.display = 'none'; };
                if (typeof Sounds !== 'undefined' && Sounds.achieve) { try { Sounds.achieve(); } catch (e) {} }
            }

            function init() {
                if (!isDemo()) return;
                document.body.classList.add('demo-build');
                applyNavGates();
                // A player who already finished the demo and reloads should not be
                // silently un-ended; re-arm the card rather than re-firing it.
                if (((state.prestige && state.prestige.count) || 0) >= (D().maxPrestige || 1)) {
                    state._demoEndShown = true;
                }
            }

            return { isDemo, init, applyNavGates, chunkAllowed, checkEnd, showEndCard };
        })();
        window.DemoMode = DemoMode;

        // ── 17. SPORE CURSOR EATING ─────────────────────────────────────────
        const SporeCursorEating = (() => {
            const CURSORS = [
                'auto',
                'url("data:image/svg+xml;utf8,<svg xmlns=\'http://www.w3.org/2000/svg\' width=\'20\' height=\'20\'><text y=\'16\' font-size=\'16\'>🍽</text></svg>") 0 0, auto',
            ];
            let _level = 0; // 0=normal, 1=nibbled, 2=half-eaten, 3=stub
            // V1.20.5.6: cursor styles removed — do not alter player cursor
            function update(happiness) {
                let newLevel = 0;
                if (happiness < 40) newLevel = 1;
                if (happiness < 20) newLevel = 2;
                if (happiness < 5)  newLevel = 3;
                if (newLevel !== _level) {
                    _level = newLevel;
                    // Only show notification at the hungriest level — no cursor change
                    if (_level === 3) showNotif('🔮 The Spore is very hungry. Feed it.', 'var(--warn-main)', 6000);
                }
            }
            function restore() { _level = 0; }
            return { update, restore };
        })();
        window.SporeCursorEating = SporeCursorEating;

        // ── 18a. CORRUPTION COMPILER — V1.20.4.9 ──────────────────────────────
        // Grimoire-equivalent: four limited-charge spells that trade instability
        // risk for production bonuses. Unlocks after first prestige.
        // Spells regenerate one charge per RECHARGE_MIN minutes automatically.
        // ─────────────────────────────────────────────────────────────────────
        const CorruptionCompiler = (() => {
            const SPELLS = [
                { id:'overclock',  name:'OVERCLOCK',       icon:'⚡', glyph:'obj_bolt',
                  desc:'Overclocks all generators — costs instability.',
                  effect:'×2 EPS for 45s', instabCost:25, maxInstab:75,
                  maxCharges:2, rechargeMin:20, duration:45000 },
                { id:'surge',      name:'SURGE PROTOCOL',  icon:'🔺', glyph:'obj_surge',
                  desc:'Extreme overclock — powerful but very dangerous.',
                  effect:'×5 EPS for 20s', instabCost:45, maxInstab:50,
                  maxCharges:1, rechargeMin:45, duration:20000 },
                { id:'flux_drain', name:'FLUX DRAIN',      icon:'💧', glyph:'obj_drain',
                  desc:'Purges entropy — reduces instability immediately.',
                  effect:'–30 instability', instabCost:0, minInstab:5,
                  maxCharges:3, rechargeMin:15 },
                { id:'echo_burst', name:'ECHO BURST',      icon:'🌀', glyph:'obj_spiral',
                  desc:'Forces a Lucky Pulse orb to spawn instantly.',
                  effect:'+1 Lucky Pulse',  instabCost:15, maxInstab:85,
                  maxCharges:2, rechargeMin:30 },
                { id:'fragment_forge', name:'FRAGMENT FORGE', icon:'◈',
                  desc:'[INTERCONNECT] Converts raw instability into Fragments. Higher instability = more fragments. Drains city awareness.',
                  effect:'+2–8 Fragments (instab-scaled)', instabCost:20, minInstab:20,
                  maxCharges:2, rechargeMin:25 },
                { id:'nexus_pulse',  name:'NEXUS PULSE',     icon:'🏙',
                  desc:'[INTERCONNECT] Sends a pulse through the city grid — triples PP gain and walker speed for 30s. Requires city awareness < 60%.',
                  effect:'×3 PP + walkers 30s', instabCost:10, maxInstab:90,
                  maxCharges:1, rechargeMin:35, duration:30000 },
            ];

            function _cs() {
                if (!state.compiler) {
                    state.compiler = {
                        charges:    { overclock:2, surge:1, flux_drain:3, echo_burst:2, fragment_forge:2, nexus_pulse:1 },
                        rechargeAt: {},
                        overclockEnd: 0,
                        surgeEnd:     0,
                    };
                }
                // Ensure new spells have charges on first access after update
                SPELLS.forEach(s => {
                    if (state.compiler.charges[s.id] === undefined)
                        state.compiler.charges[s.id] = s.maxCharges;
                });
                return state.compiler;
            }

            function tick() {
                const cs = _cs();
                const now = Date.now();
                // Reality Singularity: compiler spells recharge 50% faster
                const _singRecharge = (state.loreEffects && state.loreEffects.realitySingularity) ? 0.5 : 1.0;
                SPELLS.forEach(s => {
                    const cur = cs.charges[s.id] || 0;
                    if (cur < s.maxCharges) {
                        if (!cs.rechargeAt[s.id]) cs.rechargeAt[s.id] = now + s.rechargeMin * 60000 * _singRecharge;
                        if (now >= cs.rechargeAt[s.id]) {
                            cs.charges[s.id] = Math.min(s.maxCharges, cur + 1);
                            cs.rechargeAt[s.id] = cs.charges[s.id] < s.maxCharges
                                ? now + s.rechargeMin * 60000 * _singRecharge : 0;
                        }
                    }
                });
            }

            function getMult() {
                const cs = _cs();
                const now = Date.now();
                // V1.20.5.8: FLUX CORE aura upgrades OVERCLOCK from ×2 to ×2.5
                if (cs.surgeEnd > now)     return 5;
                if (cs.overclockEnd > now) return (window.CoreBinding && state.coreBinding && state.coreBinding.includes('flux')) ? 2.5 : 2;
                return 1;
            }

            function cast(spellId) {
                const spell = SPELLS.find(s => s.id === spellId);
                if (!spell) return;
                const cs  = _cs();
                const cur = cs.charges[spellId] || 0;
                if (cur <= 0) { showNotif('⚗ No charges — recharging…', '#ff7755', 2500); return; }
                const instab = state.instability || 0;
                if (spell.maxInstab !== undefined && instab > spell.maxInstab) {
                    showNotif(`⚗ BLOCKED — instability too high (>${spell.maxInstab}%)`, 'var(--danger-main)', 3000); return;
                }
                if (spell.minInstab !== undefined && instab < spell.minInstab) {
                    showNotif(`⚗ BLOCKED — instability too low (<${spell.minInstab}%)`, '#4488ff', 2500); return;
                }
                // Consume charge + schedule recharge
                cs.charges[spellId] = cur - 1;
                if (cs.charges[spellId] < spell.maxCharges)
                    cs.rechargeAt[spellId] = Date.now() + spell.rechargeMin * 60000;
                // Apply instability cost
                if (spell.instabCost > 0 && typeof Instability !== 'undefined') Instability.add(spell.instabCost);

                // V1.20.5.8: Artifact extension + aura-aware spell effects
                const _artExt  = window.Museum ? Museum.getCompilerExtension() : 0;
                const _bound   = state.coreBinding || [];
                const now = Date.now();

                if (spellId === 'overclock') {
                    const _dur = 45000 + _artExt;
                    cs.overclockEnd = now + _dur;
                    const _fluxAug  = _bound.includes('flux');
                    const _impactAug = _bound.includes('impact');
                    const _multLabel = _fluxAug ? '×2.5' : '×2';
                    const _durLabel  = Math.round(_dur / 1000) + 's';
                    showNotif(`⚗ OVERCLOCK — ${_multLabel} EPS for ${_durLabel}${_artExt > 0 ? ' (artifact extended)' : ''}.`, 'var(--info-main)', 4500);
                    if (_impactAug) {
                        window._compilerClickBoost = 2;
                        setTimeout(() => { window._compilerClickBoost = 1; }, _dur);
                        showNotif('💥 IMPACT SHELL surge — click power ×2 for overclock duration', 'var(--warn-main)', 4000);
                    }
                    if (window.CoreBinding) CoreBinding.notifyOverclockCast(_dur);
                    if (window.Museum) Museum.logCompilerCast('OVERCLOCK', `${_multLabel} EPS · ${_durLabel}${_fluxAug?' · Flux augmented':''}${_impactAug?' · Impact surge':''}`);
                }
                if (spellId === 'surge') {
                    const _dur = 20000 + _artExt;
                    cs.surgeEnd = now + _dur;
                    const _impactAug = _bound.includes('impact');
                    const _durLabel  = Math.round(_dur / 1000) + 's';
                    showNotif(`⚗ SURGE PROTOCOL — ×5 EPS for ${_durLabel}${_artExt > 0 ? ' (artifact extended)' : ''}!`, 'var(--warn-main)', 4500);
                    if (_impactAug) {
                        window._compilerClickBoost = 3;
                        setTimeout(() => { window._compilerClickBoost = 1; }, _dur);
                        showNotif('💥 IMPACT SHELL surge — click power ×3 for surge duration', 'var(--warn-main)', 4000);
                    }
                    if (window.Museum) Museum.logCompilerCast('SURGE PROTOCOL', `×5 EPS · ${_durLabel}${_impactAug?' · Impact surge':''}`);
                }
                if (spellId === 'flux_drain') {
                    const _dampAug  = _bound.includes('dampener');
                    const _drainAmt = _dampAug ? 45 : 30;
                    if (typeof Instability !== 'undefined') Instability.reduce(_drainAmt);
                    showNotif(`⚗ FLUX DRAIN — –${_drainAmt} instability purged${_dampAug ? ' (Dampener augmented)' : ''}.`, 'var(--success-main)', 3500);
                    if (window.CoreBinding) CoreBinding.notifyFluxDrainCast();
                    if (window.Museum) Museum.logCompilerCast('FLUX DRAIN', `–${_drainAmt} instability${_dampAug?' · Dampener augmented':''}`);
                }
                if (spellId === 'echo_burst') {
                    const _tempAug    = _bound.includes('temporal');
                    const _cascadeAug = _bound.includes('cascade');
                    if (window.LuckyPulse) LuckyPulse._forcePulse();
                    if (_cascadeAug && window.LuckyPulse) {
                        // Spawn a second pulse after 1.5s so they don't overlap
                        setTimeout(() => { if (window.LuckyPulse) LuckyPulse._forcePulse(); }, 1500);
                    }
                    if (_tempAug) {
                        state.fragments = (state.fragments || 0) + 1;
                        showNotif('⏳ TEMPORAL WEAVE — +1 fragment from ECHO BURST resonance', 'var(--lp-soft)', 3500);
                    }
                    const _echoDesc = `Lucky Pulse${_cascadeAug ? ' ×2 (Cascade)' : ''}${_tempAug ? ' · +1 frag' : ''}`;
                    showNotif(`⚗ ECHO BURST — ${_echoDesc}.`, 'var(--ducky-main)', 3000);
                    if (window.Museum) Museum.logCompilerCast('ECHO BURST', _echoDesc);
                }
                // [V1.20.8.5 INTERCONNECT] Fragment Forge: instability → fragments + awareness drain
                if (spellId === 'fragment_forge') {
                    const _instabNow = state.instability || 0;
                    let _fragGain = Math.max(2, Math.min(8, Math.floor(_instabNow / 10)));
                    // FRAGMENT TIDE aura: +50% more fragments per forge
                    const _fragTideBound = _bound.includes('frag_tide');
                    if (_fragTideBound) _fragGain = Math.floor(_fragGain * 1.5);
                    state.fragments = (state.fragments || 0) + _fragGain;
                    // Drains city awareness as a side effect
                    if (state.city) state.city.awareness = Math.max(0, (state.city.awareness || 0) - 5);
                    showNotif(`◈ FRAGMENT FORGE — +${_fragGain} fragments distilled from instability. City awareness −5%.${_fragTideBound ? ' (FRAGMENT TIDE +50%)' : ''}`, 'var(--lp-soft)', 5000);
                    if (window.Museum) Museum.logCompilerCast('FRAGMENT FORGE', `+${_fragGain} frags · −5% awareness${_fragTideBound ? ' · Tide augmented' : ''}`);
                }
                // [V1.20.8.5 INTERCONNECT] Nexus Pulse: boosts city PP and walker speed
                if (spellId === 'nexus_pulse') {
                    const _awareness = (state.city && state.city.awareness) || 0;
                    if (_awareness >= 60) {
                        showNotif('🏙 NEXUS PULSE BLOCKED — city awareness too high (≥60%). Citizens are watching.', '#ff8855', 4000);
                    } else {
                        // CITY NEXUS BIND aura: duration ×1.5, PP ×4 instead of ×3
                        const _cityNexusBound = _bound.includes('city_nexus');
                        const _dur = (_cityNexusBound ? 45000 : 30000) + _artExt;
                        const _ppMult = _cityNexusBound ? 4 : 3;
                        state._nexusPulseEnd = now + _dur;
                        state._nexusPulsePPMult = _ppMult;
                        showNotif(`🏙 NEXUS PULSE — ×${_ppMult} PP & walker speed for ${Math.round(_dur/1000)}s.${_cityNexusBound ? ' (CITY NEXUS: extended + ×4 PP)' : ''}`, 'var(--success-main)', 5000);
                        if (window.Museum) Museum.logCompilerCast('NEXUS PULSE', `×${_ppMult} PP · ${Math.round(_dur/1000)}s${_cityNexusBound ? ' · Nexus augmented' : ''}`);
                    }
                }
                render();
            }

            function render() {
                const list = document.getElementById('compiler-spell-list');
                if (!list) return;
                const cs  = _cs();
                const now = Date.now();
                const instab = state.instability || 0;
                const _bound = state.coreBinding || [];
                list.innerHTML = '';

                // V1.20.5.8: Artifact power + aura status header
                const _artExt = window.Museum ? Museum.getCompilerExtension() : 0;
                const _artCount = window.Museum ? (window.state && window.state.museum ? window.state.museum.length : 0) : 0;
                if (_artExt > 0 || _bound.some(b => b !== null)) {
                    const hdr = document.createElement('div');
                    hdr.style.cssText = 'background:rgba(20,30,60,0.6);border:1px solid rgba(60,100,180,0.35);border-radius:6px;padding:8px 12px;font-family:"Courier New",monospace;font-size:0.5rem;letter-spacing:1px;color:#5577aa;margin-bottom:6px;';
                    const _artStr = _artExt > 0 ? `◈ ${_artCount} artifacts → +${Math.round(_artExt/1000)}s duration  ` : '';
                    const _auraStr = _bound.filter(Boolean).length > 0 ? `⚗ ${_bound.filter(Boolean).length} aura${_bound.filter(Boolean).length>1?'s':''} augmenting spells` : '';
                    hdr.textContent = _artStr + _auraStr;
                    list.appendChild(hdr);
                }

                // Active effect banner
                if (cs.surgeEnd > now || cs.overclockEnd > now) {
                    const active = cs.surgeEnd > now;
                    const rem    = Math.ceil(((active ? cs.surgeEnd : cs.overclockEnd) - now) / 1000);
                    const banner = document.createElement('div');
                    banner.style.cssText = 'background:rgba(0,40,80,0.85);border:1px solid rgba(68,200,255,0.45);border-radius:6px;padding:9px 14px;font-family:\'Courier New\',monospace;font-size:0.55rem;color:#44ddff;letter-spacing:2px;margin-bottom:4px;';
                    /* the spell's own glyph (Global 6); the text is a fixed string, so innerHTML is safe here */
                    banner.innerHTML = active ? `${_objIcon({ glyph: 'obj_surge', icon: '▲' })} SURGE ACTIVE — ${rem}s remaining` : `${_objIcon({ glyph: 'obj_bolt', icon: '' })} OVERCLOCK ACTIVE — ${rem}s remaining`;
                    list.appendChild(banner);
                }

                // V1.20.5.8: aura augment lookup per spell
                const AURA_AUGMENTS = {
                    'overclock':  _bound.includes('flux')     ? '⚡ FLUX CORE: ×2.5 EPS' : (_bound.includes('impact') ? '💥 IMPACT: +click boost' : null),
                    'surge':      _bound.includes('impact')   ? '💥 IMPACT SHELL: ×3 click boost' : null,
                    'flux_drain': _bound.includes('dampener') ? '🛡 DAMPENER: –45 instab (vs –30)' : null,
                    'echo_burst': _bound.includes('temporal') ? '⏳ TEMPORAL: +1 fragment' : (_bound.includes('cascade') ? '🌀 CASCADE: ×2 pulses' : null),
                };
                // If both FLUX and IMPACT bound, OVERCLOCK benefits from both
                if (_bound.includes('flux') && _bound.includes('impact')) {
                    AURA_AUGMENTS['overclock'] = '⚡ FLUX: ×2.5 EPS + 💥 IMPACT: click boost';
                }


                // -- Instability threshold bar: shows where each spell's limits fall --
                var _compThreshBar = document.createElement('div');
                _compThreshBar.className = 'comp-instab-bar-wrap';
                var _instPct = Math.min(100, instab);
                var _compThreshLines = [];
                SPELLS.forEach(function(s) {
                    if (s.maxInstab !== undefined) _compThreshLines.push({ pct: s.maxInstab, col: 'var(--danger-main)', label: s.name + ' max ' + s.maxInstab + '%' });
                    if (s.minInstab !== undefined) _compThreshLines.push({ pct: s.minInstab, col: 'var(--brand-strong)', label: s.name + ' min ' + s.minInstab + '%' });
                });
                var _compThreshHtml = _compThreshLines.map(function(t) {
                    return '<div class="comp-thresh-line" style="left:' + t.pct + '%;border-left-color:' + t.col + ';" title="' + t.label + '"></div>';
                }).join('');
/* ⛔ §4.5 P2: the figure is stated ONCE, by the band above (#compiler-instab-display).
                       It was printed here too, and the two disagreed by rounding — 45.7% beside 46% — which
                       is also why a naive duplicate-check found nothing. The label keeps only the legend. */
                _compThreshBar.innerHTML = '<div class="comp-instab-bar-label"><span class="comp-instab-bar-legend"><span style="color:#ff6644;">| max limit</span>&nbsp;<span style="color:#44aaff;">| min limit</span></span></div><div class="comp-instab-track"><div class="comp-instab-fill" style="width:' + _instPct + '%;background:' + (instab > 75 ? '#ff3322' : instab > 50 ? 'var(--warn-main)' : '#44aacc') + ';"></div>' + _compThreshHtml + '</div>';
                /* ⭐ §4.5 P2: the meter belongs in the fixed band above the grid, not
                   as the first child of a scrolling list. Falls back to the list so the
                   panel still renders if the band is ever absent. */
                var _compBand = document.getElementById('compiler-instab-band');
                if (_compBand) {
                    var _oldBar = _compBand.querySelector('.comp-instab-bar-wrap');
                    if (_oldBar) _oldBar.remove();
                    _compBand.appendChild(_compThreshBar);
                } else {
                    list.appendChild(_compThreshBar);
                }

                SPELLS.forEach(function(spell) {
                    var charges = cs.charges[spell.id] || 0;
                    var overInstab  = spell.maxInstab !== undefined && instab > spell.maxInstab;
                    var underInstab = spell.minInstab !== undefined && instab < spell.minInstab;
                    var blocked   = overInstab || underInstab;
                    var empty     = charges <= 0;
                    var rechargeMs2 = cs.rechargeAt[spell.id];
                    var rechargeRemainMs = rechargeMs2 ? Math.max(0, rechargeMs2 - now) : 0;
                    var rechargeStr = rechargeRemainMs > 0
                        ? (rechargeRemainMs < 120000 ? Math.ceil(rechargeRemainMs / 1000) + 's' : Math.ceil(rechargeRemainMs / 60000) + 'min')
                        : '';
                    var _augTag = AURA_AUGMENTS[spell.id];
                    var _extSec = spell.duration ? Math.round((spell.duration + _artExt) / 1000) : null;

                    var _blockedTip = '';
                    if (overInstab)  _blockedTip = 'BLOCKED: Instability too high (' + Math.round(instab) + '%). Reduce below ' + spell.maxInstab + '%. Cast FLUX DRAIN to lower instability.';
                    if (underInstab) _blockedTip = 'BLOCKED: Instability too low (' + Math.round(instab) + '%). Need at least ' + spell.minInstab + '%. Click ACQUIRE rapidly to build instability.';

                    var _pipHtml = '';
                    for (var ci = 0; ci < spell.maxCharges; ci++) {
                        var _filled = ci < charges;
                        if (!_filled && ci === charges && rechargeStr) {
                            _pipHtml += '<span class="comp-charge-pip comp-charge-pip-charging" title="Recharges in ' + rechargeStr + '">' + rechargeStr + '</span>';
                        } else {
                            _pipHtml += '<span class="comp-charge-pip ' + (_filled ? 'comp-charge-pip-full' : 'comp-charge-pip-empty') + '"></span>';
                        }
                    }

                    var card = document.createElement('div');
                    card.className = 'comp-card' + (blocked || empty ? ' comp-card-dim' : '');
                    if (blocked) card.title = _blockedTip;
                    card.innerHTML =
                        '<div class="comp-card-top">'
                        + '<span class="comp-icon">' + _objIcon(spell) + '</span>'
                        + '<span class="comp-name">' + spell.name + '</span>'
                        + '<div class="comp-charge-pips">' + _pipHtml + '</div>'
                        + '</div>'
                        + '<div class="comp-effect">' + spell.effect + (_extSec ? ' <span style="color:#668899;font-size:0.48rem;">[' + _extSec + 's total]</span>' : '') + '</div>'
                        + (_augTag ? '<div style="font-size:0.38rem;color:#447799;letter-spacing:1px;margin:2px 0 0;">\u26a7 ' + _augTag + '</div>' : '')
                        + '<div class="comp-desc">' + spell.desc + '</div>'
                        + '<div class="comp-meta">'
                        + (spell.instabCost > 0 ? '<span style="color:#ff8866;">+' + spell.instabCost + '% instab</span>' : '<span style="color:#66ff88;">no instab cost</span>')
                        + (spell.maxInstab !== undefined ? ' <span class="comp-thresh-tag comp-thresh-max" title="Blocked above ' + spell.maxInstab + '% instability">MAX ' + spell.maxInstab + '%</span>' : '')
                        + (spell.minInstab !== undefined ? ' <span class="comp-thresh-tag comp-thresh-min" title="Need at least ' + spell.minInstab + '% instability">MIN ' + spell.minInstab + '%</span>' : '')
                        + (blocked ? ' <span class="comp-blocked-tag" title="' + _blockedTip.replace(/"/g, "'") + '">\u26a0 ' + (overInstab ? 'INSTAB TOO HIGH' : 'INSTAB TOO LOW') + '</span>' : '')
                        + '</div>'
                        + '<button class="comp-cast-btn" onclick="CorruptionCompiler.cast(\'' + spell.id + '\')" ' + (blocked || empty ? 'disabled' : '') + '>'
                        + (empty ? 'RECHARGING' : blocked ? 'BLOCKED' : 'COMPILE')
                        + '</button>';
                    list.appendChild(card);
                });
            }

            function init() { tick(); render(); }

            return { tick, getMult, cast, render, init };
        })();
        window.CorruptionCompiler = CorruptionCompiler;

        // ── 18b. CORE BINDING — V1.20.4.9 ─────────────────────────────────────
        // Pantheon-equivalent: three fragment slots unlocked through prestige.
        // Each slot accepts one aura — a permanent passive bonus purchased with
        // fragments. Auras can be unbound (fragments are consumed, not refunded).
        // ─────────────────────────────────────────────────────────────────────
        const CoreBinding = (() => {
            const SLOT_UNLOCK = [1, 3, 6]; // prestige count to unlock slot 0/1/2
            const AURAS = [
                { id:'flux',     icon:'⚡', glyph:'obj_bolt', name:'FLUX CORE',        cost:15, desc:'+10% passive EPS',
                  compilerSynergy: 'OVERCLOCK → ×2.5 EPS (vs ×2)' },
                { id:'impact',   icon:'💥', glyph:'obj_impact', name:'IMPACT SHELL',     cost:12, desc:'+8% click power',
                  compilerSynergy: 'SURGE → also ×2 click power for duration' },
                { id:'dampener', icon:'🛡', name:'DAMPENER CORE',    cost:20, desc:'–15% instability growth',
                  compilerSynergy: 'FLUX DRAIN → purges 45 instab (vs 30)' },
                { id:'temporal', icon:'⏳', glyph:'obj_hourglass', name:'TEMPORAL WEAVE',   cost:25, desc:'+5% LP earned',
                  compilerSynergy: 'ECHO BURST → also grants +1 fragment' },
                { id:'cascade',  icon:'🌀', glyph:'obj_spiral', name:'CASCADE RESONANCE',cost:30, desc:'+0.5% EPS per item TYPE owned (caps at 50 types)',
                  compilerSynergy: 'ECHO BURST → spawns 2 Lucky Pulses instead of 1' },
                { id:'city_nexus', icon:'🏙', name:'CITY NEXUS BIND', cost:35, desc:'+25% city diversity EPS bonus · +10% adjacency EPS',
                  compilerSynergy: 'NEXUS PULSE → duration ×1.5 · PP gain ×4 instead of ×3' },
                { id:'frag_tide', icon:'◈', name:'FRAGMENT TIDE',    cost:28, desc:'+0.05% EPS per fragment held (cap +20%)',
                  compilerSynergy: 'FRAGMENT FORGE → +50% more fragments per cast' },
            ];

            // ── V1.20.5.8: Compiler buff windows ────────────────────────────
            // When Compiler spells are cast, they can trigger timed aura upgrades.
            let _dampenerBuffEnd   = 0; // after FLUX DRAIN: DAMPENER becomes –25% for 60s
            let _cascadeBuffEnd    = 0; // after OVERCLOCK:  CASCADE doubles per-item bonus for duration

            function _slots() {
                if (!Array.isArray(state.coreBinding) || state.coreBinding.length !== 3)
                    state.coreBinding = [null, null, null];
                return state.coreBinding;
            }

            function isSlotUnlocked(i) {
                return ((state.prestige && state.prestige.count) || 0) >= SLOT_UNLOCK[i];
            }

            // Called by Compiler when FLUX DRAIN is cast
            function notifyFluxDrainCast() {
                if (_slots().includes('dampener')) {
                    _dampenerBuffEnd = Date.now() + 60000;
                    showNotif('🛡 DAMPENER CORE SURGE — instability growth –25% for 60s (FLUX DRAIN synergy)', '#44ddaa', 5000);
                }
            }

            // Called by Compiler when OVERCLOCK is cast
            function notifyOverclockCast(durationMs) {
                if (_slots().includes('cascade')) {
                    _cascadeBuffEnd = Date.now() + durationMs;
                    showNotif('🌀 CASCADE RESONANCE SURGE — per-item EPS bonus doubled for overclock duration', 'var(--brand-strong)', 5000);
                }
            }

            function getEPSMult() {
                // V1.20.5.8: Artifact resonance amplifies all aura effects
                const _artBonus = window.Museum ? Museum.getArtifactBonus() : 1;
                const now = Date.now();
                let m = 1;
                _slots().forEach(id => {
                    if (id === 'flux') m += 0.10 * _artBonus;
                    if (id === 'cascade') {
                        /* ⛔⛔ RESHAPED 2026-09-12, owner-called: "change it to item type and give
                           it an item number cap." It read the TOTAL COUNT summed across every
                           generator, with no ceiling — measured x31.09 at the 30,089 items a real
                           endgame run holds, x61.18 under an OVERCLOCK cast, while sim_economy
                           modelled the whole term as x1.000. MASTER_PLAN §8 item 2. That is the
                           collective_intel shape: an unbounded linear multiplier no simulator has
                           ever seen, and collective_intel cut the campaign 72.6h -> 15.0h.

                           ⭐ DISTINCT TYPES, NOT UNITS. Counting types makes the aura reward
                           BREADTH — owning one of each — instead of paying for depth the player
                           was buying anyway, and it is bounded by the catalogue rather than by
                           nothing. ⭐ The rate is calibrated against its own siblings, not chosen:
                           `frag_tide` costs 28 and caps at +20%, `flux` costs 15 and pays +10%
                           flat, and cascade is the most expensive aura at 30 — so +25% beats flux
                           for double the price and sits just above the capped scaler that is
                           cheaper than it. */
                        const CASCADE_PER_TYPE = 0.005;   /* +0.5% per distinct type   */
                        const CASCADE_TYPE_CAP = 50;      /* of a 105-item catalogue   */
                        const types = Object.values(state.items || {}).filter(v => (v || 0) > 0).length;
                        const counted = Math.min(types, CASCADE_TYPE_CAP);
                        /* ⚠ OVERCLOCK DOUBLES THE CAPPED BONUS, NOT THE COUNT. Doubling the type
                           count before the cap would make the advertised Compiler synergy do
                           NOTHING for any player already at 50 types — an advertised bonus that
                           silently stops applying, which is this project's most-repeated defect
                           (getSynergyMult, Urban Mirror, ppWalkSpeed). Doubling after the cap keeps
                           the synergy true at every depth. */
                        const _cascadeMult = now < _cascadeBuffEnd ? 2 : 1;
                        m += counted * CASCADE_PER_TYPE * _artBonus * _cascadeMult;
                    }
                    // [V1.20.8.5] City Nexus Bind: +10% adjacency EPS bonus
                    if (id === 'city_nexus') {
                        m += 0.10 * _artBonus;
                        // Also amplify adjacency bonus
                        if (state._adjEPS) state._adjEPS = Math.min(state._adjEPS * 1.25, 10);
                    }
                    // [V1.20.8.5] Fragment Tide: 0.05% per fragment, capped at +20%
                    if (id === 'frag_tide') {
                        const _frags = state.fragments || 0;
                        m += Math.min(0.20, _frags * 0.0005) * _artBonus;
                    }
                });
                return Math.max(1, m);
            }

            function getClickMult() {
                const _artBonus = window.Museum ? Museum.getArtifactBonus() : 1;
                let m = 1;
                _slots().forEach(id => { if (id === 'impact') m += 0.08 * _artBonus; });
                return m;
            }

            function getInstabMult() {
                const now = Date.now();
                let m = 1;
                _slots().forEach(id => {
                    if (id === 'dampener') {
                        // During FLUX DRAIN buff window: –25% instead of –15%
                        m -= (now < _dampenerBuffEnd ? 0.25 : 0.15);
                    }
                });
                return Math.max(0.1, m);
            }

            function getLPMult() {
                const _artBonus = window.Museum ? Museum.getArtifactBonus() : 1;
                let m = 1;
                _slots().forEach(id => { if (id === 'temporal') m += 0.05 * _artBonus; });
                return m;
            }

            function _previewBind(slotIdx, auraId) {
                var aura = AURAS.find(function(a){return a.id===auraId;});
                if (!aura) return;
                var slots = _slots();
                var curId = slots[slotIdx];
                var curAura = curId ? AURAS.find(function(a){return a.id===curId;}) : null;
                var _artBonus = window.Museum ? Museum.getArtifactBonus() : 1;
                var _curEPS = getEPSMult(), _curClk = getClickMult(), _curInstab = getInstabMult(), _curLP = getLPMult();
                // Simulate new binding
                var _simSlots = slots.slice(); _simSlots[slotIdx] = auraId;
                var _newEPS=1,_newClk=1,_newInstab=1,_newLP=1;
                _simSlots.forEach(function(id) {
                    if (!id) return;
                    if (id==='flux') _newEPS += 0.10*_artBonus;
                    if (id==='cascade') { var _owned=Object.values(state.items||{}).reduce(function(s,v){return s+(v||0);},0); _newEPS += _owned*0.001*_artBonus; }
                    if (id==='impact') _newClk += 0.08*_artBonus;
                    if (id==='dampener') _newInstab -= 0.15;
                    if (id==='temporal') _newLP += 0.05*_artBonus;
                });
                _newEPS=Math.max(1,_newEPS); _newInstab=Math.max(0.1,_newInstab);
                var _fragOk = (state.fragments||0) >= aura.cost;
                var modal = document.getElementById('cb-preview-modal');
                if (!modal) return;
                document.getElementById('cb-preview-title').textContent = 'BIND ' + aura.name + ' \u2192 SLOT ' + (slotIdx+1);
                document.getElementById('cb-preview-cost').textContent = aura.cost + ' fragments';
                document.getElementById('cb-preview-have').textContent = Math.floor(state.fragments||0) + ' available';
                document.getElementById('cb-preview-cost-row').style.color = _fragOk ? '#44ccaa' : 'var(--danger-main)';
                var _rows = [
                    {label:'Passive EPS',cur:(_curEPS*100-100).toFixed(1)+'%',nxt:(_newEPS*100-100).toFixed(1)+'%',better:_newEPS>_curEPS},
                    {label:'Click Power',cur:(_curClk*100-100).toFixed(1)+'%',nxt:(_newClk*100-100).toFixed(1)+'%',better:_newClk>_curClk},
                    {label:'Instab Growth',cur:(_curInstab*100).toFixed(0)+'%',nxt:(_newInstab*100).toFixed(0)+'%',better:_newInstab<_curInstab},
                    {label:'LP Bonus',cur:(_curLP*100-100).toFixed(1)+'%',nxt:(_newLP*100-100).toFixed(1)+'%',better:_newLP>_curLP},
                ];
                document.getElementById('cb-preview-rows').innerHTML = _rows.map(function(r){
                    var arrow=r.better?'<span style="color:#44ff88;">\u2191</span>':(r.cur===r.nxt?'<span style="color:#556677;">=</span>':'<span style="color:#ff6644;">\u2193</span>');
                    return '<div class="cb-prev-row"><span class="cb-prev-lbl">'+r.label+'</span><span class="cb-prev-cur">'+r.cur+'</span><span class="cb-prev-arrow">'+arrow+'</span><span class="cb-prev-nxt'+(r.better?' cb-prev-better':'')+'">'+r.nxt+'</span></div>';
                }).join('');
                var warnEl=document.getElementById('cb-preview-warn');
                if (curAura) { warnEl.style.display=''; warnEl.innerHTML='\u26a0 DESTRUCTIVE: Replacing <strong>'+curAura.name+'</strong>. Fragments consumed, not recovered.'; }
                else { warnEl.style.display='none'; }
                document.getElementById('cb-preview-aura-desc').textContent=aura.icon+' '+aura.name+' \u2014 '+aura.desc;
                var synEl=document.getElementById('cb-preview-synergy');
                if (aura.compilerSynergy){synEl.style.display='';synEl.textContent='\u26a7 Compiler: '+aura.compilerSynergy;}
                else{synEl.style.display='none';}
                var confirmBtn=document.getElementById('cb-preview-confirm');
                confirmBtn.disabled=!_fragOk;
                confirmBtn.textContent=curAura?'CONFIRM REPLACE':'CONFIRM BIND';
                confirmBtn.onclick=function(){modal.style.display='none';bind(slotIdx,auraId);};
                document.getElementById('cb-preview-cancel').onclick=function(){modal.style.display='none';};
                modal.style.display='flex';
            }

            function _previewUnbind(slotIdx) {
                var slots=_slots(); var curId=slots[slotIdx];
                var curAura=curId?AURAS.find(function(a){return a.id===curId;}):null;
                if (!curAura) return;
                var modal=document.getElementById('cb-preview-modal');
                if (!modal) return;
                document.getElementById('cb-preview-title').textContent='UNBIND '+curAura.name;
                document.getElementById('cb-preview-cost').textContent='Cost: '+curAura.cost+' fragments (not refunded)';
                document.getElementById('cb-preview-have').textContent='Slot '+(slotIdx+1)+' becomes empty';
                document.getElementById('cb-preview-cost-row').style.color='var(--warn-main)';
                document.getElementById('cb-preview-rows').innerHTML='<div class="cb-prev-row"><span class="cb-prev-lbl" style="color:#ff6644;">\u26a0 This permanently removes the bonus</span></div>';
                var warnEl=document.getElementById('cb-preview-warn');
                warnEl.style.display='';
                warnEl.innerHTML='\u26a0 The '+curAura.cost+' fragments spent binding <strong>'+curAura.name+'</strong> are consumed. Unbinding does NOT refund them.';
                document.getElementById('cb-preview-aura-desc').textContent=curAura.icon+' '+curAura.name+' \u2014 '+curAura.desc;
                document.getElementById('cb-preview-synergy').style.display='none';
                var confirmBtn=document.getElementById('cb-preview-confirm');
                confirmBtn.disabled=false; confirmBtn.textContent='CONFIRM UNBIND';
                confirmBtn.onclick=function(){modal.style.display='none';unbind(slotIdx);};
                document.getElementById('cb-preview-cancel').onclick=function(){modal.style.display='none';};
                modal.style.display='flex';
            }

            function bind(slotIdx, auraId) {
                if (!isSlotUnlocked(slotIdx)) { showNotif('◈ Slot locked — prestige to unlock.', '#886644', 2500); return; }
                const aura = AURAS.find(a => a.id === auraId);
                if (!aura) return;
                if ((state.fragments || 0) < aura.cost) {
                    showNotif(`◈ Need ${aura.cost} fragments (have ${Math.floor(state.fragments||0)}).`, 'var(--danger-main)', 3000); return;
                }
                if (_slots().includes(auraId)) { showNotif('◈ Aura already bound in another slot.', '#886644', 2500); return; }
                state.fragments -= aura.cost;
                state.coreBinding[slotIdx] = auraId;
                showNotif(`◈ ${aura.name} bound — ${aura.desc}`, '#aaffcc', 4000);
                render();
            }

            function unbind(slotIdx) {
                if (!_slots()[slotIdx]) return;
                const aura = AURAS.find(a => a.id === _slots()[slotIdx]);
                state.coreBinding[slotIdx] = null;
                showNotif(`◈ ${aura ? aura.name : 'Aura'} unbound. Fragments consumed.`, '#886644', 2500);
                render();
            }

            function render() {
                const panel = document.getElementById('binding-slots-list');
                if (!panel) return;
                const slots = _slots();
                const fragEl = document.getElementById('binding-frag-display');
                if (fragEl) fragEl.textContent = Math.floor(state.fragments || 0);

                // ── §4.5 PORT: the v3 rail's live state ──────────────────────
                // ⚠ AGAINST *OPEN* SOCKETS, NOT AGAINST THREE. SLOT_UNLOCK is
                // [1,3,6], so a player at prestige 1 has one socket; a rail reading
                // "0/3" would be telling them they are missing two things they
                // cannot have yet. Naming the next unlock is the part that answers
                // the owner's "I don't know much about what Binding actually does".
                // ⭐ Derived from SLOT_UNLOCK every render — never restated, so the
                // aura table and this line cannot drift apart.
                const railEl = document.getElementById('binding-rail-state');
                if (railEl) {
                    const _open  = slots.filter((_, i) => isSlotUnlocked(i)).length;
                    const _bound = slots.filter(Boolean).length;
                    let _txt = _bound + '/' + _open + ' BOUND';
                    if (_open < SLOT_UNLOCK.length)
                        _txt += ' · SLOT ' + (_open + 1) + ' AT P' + SLOT_UNLOCK[_open];
                    railEl.textContent = _txt;
                }
                panel.innerHTML = '';

                // ── V1.20.5.8: Artifact Resonance header ────────────────────
                const _artCount = window.Museum ? Museum.getArtifactBonus() : 1;
                const _artPct   = Math.round((_artCount - 1) * 100);
                if (_artPct > 0) {
                    const hdr = document.createElement('div');
                    hdr.style.cssText = 'background:rgba(60,20,100,0.35);border:1px solid rgba(140,80,220,0.3);border-radius:6px;padding:8px 12px;margin-bottom:8px;font-family:"Courier New",monospace;font-size:0.5rem;letter-spacing:2px;color:#9966cc;';
                    hdr.innerHTML = `◈ ARTIFACT RESONANCE +${_artPct}% — all bound aura effects amplified by museum artifacts`;
                    panel.appendChild(hdr);
                }

                // ── Active compiler buff windows ─────────────────────────────
                const now2 = Date.now();
                const _dBuff = now2 < _dampenerBuffEnd;
                const _cBuff = now2 < _cascadeBuffEnd;
                if (_dBuff || _cBuff) {
                    const buffEl = document.createElement('div');
                    buffEl.style.cssText = 'background:rgba(0,40,60,0.5);border:1px solid rgba(40,160,200,0.4);border-radius:6px;padding:8px 12px;margin-bottom:8px;font-family:"Courier New",monospace;font-size:0.5rem;letter-spacing:1px;color:#44bbcc;';
                    buffEl.innerHTML = `⚗ COMPILER SURGE ACTIVE${_dBuff ? ` — DAMPENER –25% (${Math.ceil((_dampenerBuffEnd-now2)/1000)}s)` : ''}${_cBuff ? ` — CASCADE ×2 (${Math.ceil((_cascadeBuffEnd-now2)/1000)}s)` : ''}`;
                    panel.appendChild(buffEl);
                }

                for (let i = 0; i < 3; i++) {
                    const unlocked   = isSlotUnlocked(i);
                    const boundId    = slots[i];
                    const boundAura  = boundId ? AURAS.find(a => a.id === boundId) : null;
                    const slotEl     = document.createElement('div');
                    slotEl.className = 'cb-slot' + (unlocked ? '' : ' cb-locked');

                    if (!unlocked) {
                        slotEl.innerHTML = `<div class="cb-slot-header">SLOT ${i+1}
                            <span class="cb-req-badge">Requires ${SLOT_UNLOCK[i]} prestige${SLOT_UNLOCK[i]>1?'s':''}</span></div>
                            <div class="cb-slot-body" style="color:#334455;font-size:0.55rem;letter-spacing:2px;">◈ LOCKED</div>`;
                    } else if (boundAura) {
                        // V1.20.5.8: show compiler synergy tag on bound auras
                        const _synTag = boundAura.compilerSynergy
                            ? `<div style="margin-top:4px;font-size:0.36rem;color:#447799;letter-spacing:1px;">⚗ ${boundAura.compilerSynergy}</div>`
                            : '';
                        slotEl.innerHTML = `<div class="cb-slot-header">SLOT ${i+1}
                            <span class="cb-bound-badge">BOUND</span></div>
                            <div class="cb-bound-aura">
                                <span class="cb-aura-icon">${_objIcon(boundAura)}</span>
                                <div class="cb-aura-info">
                                    <div class="cb-aura-name">${boundAura.name}</div>
                                    <div class="cb-aura-eff">${boundAura.desc}${_artPct > 0 ? ` <span style="color:#9966cc;">(+${_artPct}% resonance)</span>` : ''}</div>
                                    ${_synTag}
                                </div>
                                <button class="cb-unbind-btn" onclick="CoreBinding._previewUnbind(${i})">UNBIND</button>
                            </div>`;
                    } else {
                        const available = AURAS.filter(a => !slots.includes(a.id));
                        const opts = available.map(a => `
                            <div class="cb-aura-opt" onclick="CoreBinding._previewBind(${i},'${a.id}')">
                                <span class="cb-aura-icon">${_objIcon(a)}</span>
                                <div class="cb-aura-info">
                                    <div class="cb-aura-name">${a.name}</div>
                                    <div class="cb-aura-eff">${a.desc}</div>
                                    <div style="font-size:0.36rem;color:#336655;letter-spacing:1px;margin-top:2px;">⚗ ${a.compilerSynergy}</div>
                                </div>
                                <span class="cb-aura-cost">${a.cost} ◈</span>
                            </div>`).join('');
                        slotEl.innerHTML = `<div class="cb-slot-header">SLOT ${i+1}
                            <span class="cb-empty-badge">EMPTY</span></div>
                            <div class="cb-aura-list">${opts || '<div style="color:#334455;font-size:0.55rem;padding:8px;">All auras bound in other slots.</div>'}</div>`;
                    }
                    panel.appendChild(slotEl);
                }
            }

            function init() { _slots(); render(); }

            return { getEPSMult, getClickMult, getInstabMult, getLPMult, bind, unbind, _previewBind, _previewUnbind, render, init, notifyFluxDrainCast, notifyOverclockCast };
        })();
        window.CoreBinding = CoreBinding;

        // ── 18. LUCKY PULSE — V1.20.4.7 ──────────────────────────────────────
        // Randomly spawns a golden orb near the click button every 3–9 minutes.
        // The orb lives for 13 seconds; clicking it grants one of three bonuses.
        // Inspired by Cookie Clicker's Golden Cookie mechanic — designed to reward
        // active players without penalising idle players.
        //
        // Bonuses (weighted):
        //   ENERGY SURGE  (50%) — instantly grant 15 min of current passive EPS
        //   AMPLIFY        (35%) — ×3 EPS multiplier for 60 seconds
        //   JACKPOT        (15%) — 60 min of passive EPS + 5-second ×5 click burst
        // ─────────────────────────────────────────────────────────────────────
        const LuckyPulse = (() => {
            // ── Config ────────────────────────────────────────────────────────
            /* ⭐ IT ARRIVES ON A MOMENT (owner call, 2026-09-25; PLAYTEST_REVIEW §6: "more purposeful triggering"). It used
               to spawn every 3–9 minutes at random. Now a combo reaching FRENZY summons it (at most once per
               MOMENT_GAP_MS), so it is a reward for playing rather than a coin that drifts past; the timer below is only
               the fallback that keeps it alive for a player who never chains, and it is slower than before. */
            const SPAWN_MIN_MS   = 10 * 60 * 1000;  // fallback: 10 min earliest next spawn
            const SPAWN_MAX_MS   = 15 * 60 * 1000;  // fallback: 15 min latest  next spawn
            const MOMENT_GAP_MS  = 3 * 60 * 1000;   // a moment can summon it once per 3 min
            const LIFETIME_MS    = 13 * 1000;        // orb lives for 13 seconds
            const FADE_MS        = 400;              // CSS fade duration (matches .4s transition)

            /* ── OUTCOME TABLE — V1.21.2.1, OWNER DECISION ─────────────────────────
               "Instead of giving you a multiplier, it can have a random effect. Clicking
                some times might give you something good, but other times it will turn
                into an unlucky pulse and do something bad."

               ⭐ THE ORB LOOKS THE SAME UNTIL IT IS CLICKED. The outcome is rolled on
               click, not on spawn, so the gamble is the mechanic and the reward flash is
               the reveal — that is what "turns into an unlucky pulse" means here.

               ⛔ THE WORST LOSS IS DELIBERATELY SMALLER THAN THE SMALLEST GAIN. `levy`
               takes five minutes of income; the weakest good outcome grants fifteen. So a
               player who clicks every orb they see is ahead over any real number of rolls,
               and a run cannot be destroyed by bad luck on one click. 70 good / 30 bad. */
            const BONUSES = [
                { id: 'surge',   weight: 32, label: '⚡ ENERGY SURGE',   color: '#44ddff',           bgColor: 'rgba(0,30,60,0.92)' },
                { id: 'amplify', weight: 25, label: '× AMPLIFY',         color: '#aaffaa',           bgColor: 'rgba(0,30,10,0.92)' },
                { id: 'jackpot', weight: 13, label: '★ JACKPOT',         color: 'var(--ducky-main)', bgColor: 'rgba(40,20,0,0.92)' },
                /* ── the unlucky half ───────────────────────────────────────────── */
                { id: 'static',  weight: 13, bad: true, label: '◈ STATIC DISCHARGE', color: 'var(--warn-main)',   bgColor: 'rgba(50,25,0,0.92)' },
                { id: 'drain',   weight: 12, bad: true, label: '▼ POWER DRAIN',      color: 'var(--danger-main)', bgColor: 'rgba(50,0,10,0.92)' },
                { id: 'levy',    weight: 5,  bad: true, label: '✖ COLLECTION NOTICE', color: 'var(--danger-main)', bgColor: 'rgba(40,0,25,0.92)' },
            ];

            // ── State ─────────────────────────────────────────────────────────
            let _orb        = null;  // #lucky-pulse element
            let _lbl        = null;  // #lucky-pulse-label element
            let _spawnTimer = null;  // setTimeout for next spawn
            let _aliveTimer = null;  // setTimeout for auto-dismiss after LIFETIME_MS
            let _cntRaf     = null;  // rAF id for countdown ring update
            let _spawnedAt  = 0;     // Date.now() when orb appeared
            let _active     = false; // true while orb is on screen and clickable
            let _amplifyEnd = 0;     // timestamp when AMPLIFY bonus expires
            let _drainEnd   = 0;     // timestamp when the unlucky DRAIN expires
            let _lastSpawnAt = 0;    // when an orb last appeared (moments respect MOMENT_GAP_MS)

            // ── Helpers ───────────────────────────────────────────────────────
            function _weightedPick() {
                const total = BONUSES.reduce((s, b) => s + b.weight, 0);
                let r = Math.random() * total;
                for (const b of BONUSES) { r -= b.weight; if (r <= 0) return b; }
                return BONUSES[0];
            }

            // Returns the element's viewport center as {x, y}
            function _btnCenter() {
                const btn = document.getElementById('click-btn') || document.getElementById('click-btn-img');
                if (!btn) return { x: window.innerWidth / 2, y: window.innerHeight / 2 };
                const r = btn.getBoundingClientRect();
                return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
            }

            // Position orb at a random offset around the click button
            /* ⛔ OFF THE BUTTON, NOT ON ITS RIM. The radius was a fixed 90–150px from the
               button's centre, and ACQUIRE is wider than that, so the orb routinely landed on
               the button itself — a player clicking fast would hit it without seeing it, and
               the roll (a third of which is bad) happened to them rather than being chosen.
               PLAYTEST_REVIEW §6: "appears too randomly with no clear purpose". Measured by
               tools/probe_core_gameplay.js. The ring now starts outside the button's own
               radius plus the orb's, so taking the pulse is always a separate, deliberate click. */
            function _btnRadius() {
                const btn = document.getElementById('click-btn-img-wrap') || document.getElementById('click-btn');
                if (!btn) return 110;
                const r = btn.getBoundingClientRect();
                return Math.max(r.width, r.height) / 2;
            }
            function _placeOrb() {
                const c   = _btnCenter();
                const ang = Math.random() * Math.PI * 2;
                const rad = _btnRadius() + 27 + 18 + Math.random() * 70; // clear of the button: its radius + orb radius + 18px
                const ox  = c.x + Math.cos(ang) * rad - 27; // 27 = half orb size
                const oy  = c.y + Math.sin(ang) * rad - 27;
                // Clamp to visible viewport, keeping orb and label clear of nav bar.
                // Bottom boundary: nav bar (--nav-h = 64px) + orb height (54px) + label (26px) = 144px.
                // Top boundary: 80px to avoid the energy display / instability bar at the top.
                const x   = Math.max(10, Math.min(window.innerWidth  - 64, ox));
                const y   = Math.max(80, Math.min(window.innerHeight - 144, oy));
                _orb.style.left = x + 'px';
                _orb.style.top  = y + 'px';
                _lbl.style.left = (x - 20) + 'px';  // slightly wider than orb
                _lbl.style.top  = (y + 58) + 'px';  // just below orb
            }

            // Animate the countdown ring via CSS custom property --lp-pct
            function _startCountdown() {
                function _tick() {
                    if (!_active) return;
                    const elapsed = Date.now() - _spawnedAt;
                    const pct     = Math.max(0, 1 - elapsed / LIFETIME_MS);
                    if (_orb) _orb.style.setProperty('--lp-pct', (pct * 100).toFixed(1) + '%');
                    _cntRaf = requestAnimationFrame(_tick);
                }
                _cntRaf = requestAnimationFrame(_tick);
            }

            // ── Spawn ──────────────────────────────────────────────────────────
            function _spawn() {
                // Don't spawn while game is not running or during menus
                /* ⛔⛔ THIS GUARD KILLED THE WHOLE FEATURE, TWICE OVER, AND SILENTLY.
                   It read `!window.isRunning || getElementById('main-menu')?.style.display
                   !== 'none'`. `isRunning` is a script-scope let, so `window.isRunning` is
                   undefined and `!undefined` is true — an unconditional return. And
                   `#main-menu` is not an element in this build (the seven matches in
                   index.html are CSS class names), so the optional chain yields undefined
                   and `undefined !== 'none'` is ALSO true. Two independent early returns in one
                   `if`, neither of which throws.
                   ⚠ Written OUT rather than chained on purpose: a missing element must mean
                   "the menu is not up, so spawning is fine", and `?.` gives the opposite. */
                const _hs = document.getElementById('home-screen');
                const _menuUp = !!(_hs && getComputedStyle(_hs).display !== 'none');
                if (!isRunning || _menuUp) {
                    _scheduleNext();
                    return;
                }
                _orb = document.getElementById('lucky-pulse');
                _lbl = document.getElementById('lucky-pulse-label');
                if (!_orb || !_lbl) { _scheduleNext(); return; }

                _active   = true;
                _spawnedAt = Date.now();
                _lastSpawnAt = _spawnedAt;

                _orb.style.display = '';
                /* the game's own glyph, not a gold coin (owner call, 2026-09-25): a hex cell about to discharge */
                if (!_orb.firstElementChild && window.UIGlyph) _orb.innerHTML = '<span class="ui-glyph lp-glyph" aria-hidden="true">' + UIGlyph.get('obj_pulse') + '</span>';
                _lbl.textContent = 'LUCKY PULSE';

                // Reflow so transitions fire from opacity:0
                void _orb.offsetWidth;
                _orb.classList.add('lp-visible');
                _lbl.classList.add('lp-visible');

                _placeOrb();
                _startCountdown();

                // Auto-dismiss after LIFETIME_MS
                _aliveTimer = setTimeout(_dismiss, LIFETIME_MS);
            }

            // ── Dismiss (no click) ─────────────────────────────────────────────
            function _dismiss() {
                if (!_active) return;
                _active = false;
                cancelAnimationFrame(_cntRaf);
                clearTimeout(_aliveTimer);
                if (_orb) { _orb.classList.remove('lp-visible'); _orb.classList.add('lp-fading'); }
                if (_lbl) { _lbl.classList.remove('lp-visible'); _lbl.classList.add('lp-fading'); }
                setTimeout(() => {
                    if (_orb) { _orb.style.display = 'none'; _orb.classList.remove('lp-fading'); }
                    if (_lbl) { _lbl.classList.remove('lp-fading'); }
                }, FADE_MS + 50);
                _scheduleNext();
            }

            // ── Apply bonus ────────────────────────────────────────────────────
            function _applyBonus(bonus, clickX, clickY) {
                /* Step 2: the ONE place a base rate is correct. `surge` grants 15 minutes of
                   income as a lump sum; paying it from the true rate would let a player bank
                   150 minutes by claiming it inside Redline (x10), now reachable after Step 1. */
                const pps = _getSustainedEPS();
                let notifText = '';
                if (bonus.id === 'surge') {
                    // 15 minutes of passive EPS as an instant grant
                    const gain = Math.max(1, pps * 60 * 15);
                    if (state) state.energy = Math.min(Number.MAX_VALUE, (state.energy || 0) + gain);
                    notifText = `⚡ ENERGY SURGE — +${format(gain)} energy`;
                } else if (bonus.id === 'amplify') {
                    // ×3 EPS for 60 seconds via a temporary multiplier on state
                    _amplifyEnd = Date.now() + 60000;
                    if (state) state._lpAmplifyEnd = _amplifyEnd;
                    notifText = '× AMPLIFY — ×3 EPS for 60 seconds';
                } else if (bonus.id === 'jackpot') {
                    // 60 minutes of passive EPS + 5-second click burst
                    const gain = Math.max(1, pps * 60 * 60);
                    if (state) state.energy = Math.min(Number.MAX_VALUE, (state.energy || 0) + gain);
                    if (Prestige && Prestige.triggerBurst) Prestige.triggerBurst(5000);
                    notifText = `★ JACKPOT — +${format(gain)} energy + click burst`;
                    // V1.20.5.7 INTERCONNECT: jackpot energy surge feeds the Spore
                    // — the burst radiates enough ambient energy to sate it partially
                    if (state && window.BlissfulSpore) {
                        const _sh = BlissfulSpore._getHappiness ? BlissfulSpore._getHappiness() : 100;
                        if (_sh < 80) {
                            state.instability = Math.max(0, (state.instability || 0) - 8);
                            setTimeout(() => showNotif('🔮 The Spore absorbed the pulse residual. It seems briefly satisfied.', '#88cc88', 4000), 1200);
                        }
                    }
                }
                /* ── the unlucky half ─────────────────────────────────────────────
                   ⚠ STORY_ARC §6: state the fact, name the cost, do not draw the
                   conclusion. These say what was taken and then stop. */
                else if (bonus.id === 'static') {
                    const before = state.instability || 0;
                    state.instability = Math.min(100, before + 12);
                    notifText = '◈ STATIC DISCHARGE — instability +'
                              + Math.round(state.instability - before) + '%';
                } else if (bonus.id === 'drain') {
                    /* Routed through the SAME accessor the amplify bonus uses, so the gain
                       chain keeps exactly one Lucky Pulse term. A second term would be a
                       second place for this to be applied twice, or not at all. */
                    _drainEnd = Date.now() + 45000;
                    state._lpDrainEnd = _drainEnd;
                    notifText = '▼ POWER DRAIN — output halved for 45 seconds';
                } else if (bonus.id === 'levy') {
                    /* Five minutes of income, never more — bounded against the RATE, not
                       against the balance, so it cannot scale into a run-ending loss at the
                       top end where energy spans thirty orders of magnitude. */
                    const loss = Math.max(1, Math.min(pps * 60 * 5, (state.energy || 0) * 0.10));
                    state.energy = Math.max(0, (state.energy || 0) - loss);
                    notifText = '✖ COLLECTION NOTICE — −' + format(loss) + ' energy';
                }
                if (window.showNotif) showNotif(notifText, bonus.color, 5000);
                /* ⭐ THE AMOUNT GOES WHERE THE PLAYER IS LOOKING. The flash used to show only the
                   label ("⚡ ENERGY SURGE") and the number went to the notification column — which a
                   player mid-click is not watching, so the counter simply jumped by a few hundred
                   with no reason on screen. PLAYTEST_REVIEW §6: "occasional unexplained +500 energy".
                   The notification keeps the full sentence; the flash now carries the fact. */
                _spawnRewardFlash(bonus, clickX, clickY, notifText.split(' — ').slice(1).join(' — '));
                if (state && state.stats) {
                    state.stats.luckyPulsesClicked = (state.stats.luckyPulsesClicked || 0) + 1;
                }
            }

            // Spawn a floating reward label at click position
            function _spawnRewardFlash(bonus, x, y, detail) {
                const el = document.createElement('div');
                el.className = 'lp-reward-flash';
                el.textContent = bonus.label + (detail ? '  ' + detail : '');
                el.style.left  = (x - 60) + 'px';
                el.style.top   = (y - 10) + 'px';
                el.style.color = bonus.color;
                el.style.background = bonus.bgColor;
                el.style.border = `1px solid ${bonus.color}44`;
                document.body.appendChild(el);
                setTimeout(() => el.remove(), 2600);
            }

            // ── Click handler ──────────────────────────────────────────────────
            function _onClick(e) {
                if (!_active) return;
                _active = false;
                cancelAnimationFrame(_cntRaf);
                clearTimeout(_aliveTimer);
                const bonus = _weightedPick();
                _applyBonus(bonus, e.clientX, e.clientY);
                _dismiss();
                // Immediately re-hide (dismiss also hides, but be safe)
                if (_orb) { _orb.classList.remove('lp-visible'); }
                if (_lbl) { _lbl.classList.remove('lp-visible'); }
            }

            // ── Schedule next spawn ────────────────────────────────────────────
            function _scheduleNext() {
                // V1.20.5.7 INTERCONNECT: high instability (>70%) accelerates Lucky Pulse spawns by 20%
                // — chaos creates opportunity; volatile systems leak energy bursts
                const _instabBoost = (state && (state.instability || 0) > 70) ? 0.8 : 1;
                const delay = (SPAWN_MIN_MS + Math.random() * (SPAWN_MAX_MS - SPAWN_MIN_MS)) * _instabBoost;
                _spawnTimer = setTimeout(_spawn, delay);
            }

            // ── Amplify multiplier accessor (called from passive EPS loop) ─────
            /* ⭐ ONE ACCESSOR FOR BOTH DIRECTIONS. The gain chain reads this at exactly
               two sites, and both now cover the unlucky `drain` as well as the lucky
               `amplify` — adding a second term for the penalty would have created a
               second place for it to be double-applied or silently dropped, which is the
               defect MATH_AUDIT §1 records against the Run Mutation multipliers.
               ⚠ Amplify wins a tie: a player who earns a bonus and then a penalty is not
               left worse off than one who clicked nothing. */
            function getAmplifyMult() {
                const now = Date.now();
                if (_amplifyEnd > 0 && now < _amplifyEnd) return 3;
                if (_amplifyEnd) { _amplifyEnd = 0; if (state) state._lpAmplifyEnd = 0; }
                if (_drainEnd > 0 && now < _drainEnd) return 0.5;
                if (_drainEnd) { _drainEnd = 0; if (state) state._lpDrainEnd = 0; }
                return 1;
            }

            // ── Init ───────────────────────────────────────────────────────────
            function init() {
                // Wire up click + keyboard events
                const orb = document.getElementById('lucky-pulse');
                if (orb) {
                    orb.addEventListener('click',   _onClick);
                    orb.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); _onClick(e); } });
                }
                // Restore amplify / drain end from save (if mid-session reload)
                if (state && state._lpAmplifyEnd) {
                    _amplifyEnd = state._lpAmplifyEnd;
                }
                /* ⚠ A drain that outlived a reload must come back, or reloading
                   becomes the way to dodge the unlucky half. */
                if (state && state._lpDrainEnd > Date.now()) _drainEnd = state._lpDrainEnd;
                // The fallback clock only — the first pulse most players see is a moment (onMoment, below)
                _scheduleNext();
            }

            /* A moment summons the orb: Combo calls this when a chain reaches FRENZY. */
            function onMoment(kind) {
                if (_active || !isRunning) return false;
                if (_lastSpawnAt && Date.now() - _lastSpawnAt < MOMENT_GAP_MS) return false;
                clearTimeout(_spawnTimer);
                _spawn();
                return _active;
            }

            // ── Force spawn — called by ECHO BURST spell ──────────────────────
            function _forcePulse() {
                clearTimeout(_spawnTimer);
                clearTimeout(_aliveTimer);
                if (_active) _dismiss();
                // Schedule the forced spawn after a short delay so dismiss() finishes
                setTimeout(_spawn, 150);
            }

            // ── Cancel — called by EndSeq to suppress all pending orbs ──────────
            function cancel() {
                clearTimeout(_spawnTimer);
                clearTimeout(_aliveTimer);
                cancelAnimationFrame(_cntRaf);
                _active = false;
                if (_orb) {
                    _orb.classList.remove('lp-visible');
                    _orb.style.display = 'none';
                }
                if (_lbl) {
                    _lbl.classList.remove('lp-visible');
                }
            }

            /* ⚠ QA hook, same shape as `_forcePulse` above and gamepad.js's
               `_injectTestPad`. The outcome is a WEIGHTED ROLL, so a suite that clicked
               orbs and waited to see a `levy` would be flaky and would still never prove
               the 5%-weight branch works. This drives one named outcome directly. */
            function _qaApply(id) {
                const b = BONUSES.find(x => x.id === id);
                if (b) _applyBonus(b, 0, 0);
                return !!b;
            }
            return { init, getAmplifyMult, cancel, _forcePulse, _qaApply, onMoment };
        })();
        window.LuckyPulse = LuckyPulse;


        /* ══════════════════════════════════════════════════════════════
           V1.20.5.1 — FLAVOR TICKER  /  V1.20.5.2 — UI & OVERLAY POLISH
           Passive news-ticker with game-state-aware humorous messages.
           Shows when the world-event-ticker is idle (no active event).
           Inspired by Cookie Clicker's scrolling news bar.
        ══════════════════════════════════════════════════════════════ */
        const FlavorTicker = (() => {
            const INTERVAL_MS = 40000; // one message every ~40 seconds
            let _timerId = null;

            // ── Message pool ──────────────────────────────────────────────
            // Each entry: { text, color, cond } — cond(state) must be truthy to use it.
            // When cond is omitted the message is always eligible.
            /* ⚠ A line that states a fact must be gated on the fact (2026-09-23). "Passive income has
               been detected" and "Your click pattern has been logged" were in the ALWAYS pool and
               were measured playing to a fresh game with 0 clicks and 0 generators. */
            const _clicked = s => (s.totalClicks || 0) > 0;
            const _automated = s => { try { return ITEMS.some(i => i.type === 'auto' && ((s.items && s.items[i.id]) || 0) > 0); } catch (e) { return false; } };
            const _MSG = [
                // ── Ambient / always-available ───────────────────────────
                { text: 'The simulation has been running for longer than you know.' },
                { text: 'Energy is not created or destroyed. It is merely... rerouted.' },
                { text: 'Somewhere, a data center is very warm because of you.' },
                { text: 'Your click pattern has been logged. The simulation approves.', cond: _clicked },
                { text: 'The auto-generators do not sleep. Neither, apparently, do you.', cond: _automated },
                { text: 'Processing. Always processing.' },
                { text: 'The numbers go up. This is considered progress.' },
                { text: 'Some Operators ask why. The wise ones just click.' },
                { text: 'Entropy is a problem for someone else to solve.' },
                { text: 'Your idle income is generating heat. Thank you for your contribution.', cond: _automated },
                { text: 'This terminal has seen things. It is not required to share them.' },
                { text: 'OPERATOR PERFORMANCE: adequate. Continued engagement: expected.' },
                { text: 'No anomalies detected. This message is logged regardless.' },
                { text: 'The simulation notes your presence. The simulation does not say how it feels about it.' },
                { text: 'ENERGY THROUGHPUT: nominal. EXISTENTIAL RISK: also nominal. Proceed.' },
                { text: 'Click responsibly. The click button is watching.' },
                { text: 'Automated systems are handling the boring parts. You are handling the clicking part.', cond: s => _automated(s) && _clicked(s) },
                { text: 'The null entity sends its regards. You did not ask for them.' },
                { text: 'Previous Operators averaged 2.3 playthroughs. You are already an outlier.' },
                { text: 'Passive income has been detected. The simulation is impressed. The simulation is lying.', cond: _automated },

                // ── Early game (energy < 1 000 000) ─────────────────────
                { text: 'The Hamster Wheel spins. The hamster has questions.',
                  cond: s => (s.energy||0) < 1e6 && ((s.items && s.items['hamster']) || 0) > 0 },
                { text: 'First prestige unlocks at 1 billion energy. You\'ll get there. Probably.',
                  cond: s => (s.energy||0) < 1e6 && !((s.prestige&&s.prestige.count)||0) },
                { text: 'You are generating energy. The energy is going somewhere. Please don\'t ask where.',
                  cond: s => (s.energy||0) < 1e6 && (_clicked(s) || _automated(s)) },
                { text: 'Your productivity has been noted and immediately commodified.',
                  cond: s => (s.energy||0) < 1e6 && _clicked(s) },
                /* was s.items['hamster_wheel'] — the item id is 'hamster', so this line had never shown */
                { text: 'HAMSTER: currently enjoying its rotation. OPERATOR: currently watching.',
                  cond: s => (s.items&&(s.items['hamster']||0)) > 0 },

                // ── Mid game ─────────────────────────────────────────────
                { text: 'Your Crypto Miner is mining something. The blockchain is confused.',
                  cond: s => s.items&&(s.items['crypto_miner']||0) > 0 },
                { text: 'The CAPTCHA Farm has failed thousands of captchas on your behalf. Efficiency.',
                  cond: s => s.items&&(s.items['captcha_farm']||0) > 0 },
                { text: 'Your generators have achieved sentience. They have chosen to keep working anyway.',
                  cond: s => (s.energy||0) >= 1e6 && (s.energy||0) < 1e9 },
                { text: 'The simulation detects elevated engagement. This is expected.',
                  cond: s => (s.energy||0) >= 1e5 },

                // ── High instability ─────────────────────────────────────
                { text: 'Instability detected. The simulation recommends continued engagement.',
                  color: '#cc8844', cond: s => (s.instability||0) >= 40 },
                { text: 'The walls are becoming slightly less defined at the edges. Normal.',
                  color: '#cc8844', cond: s => (s.instability||0) >= 50 },
                { text: 'Something is watching the instability gauge. It is smiling.',
                  color: 'var(--warn-main)', cond: s => (s.instability||0) >= 60 },
                { text: 'At 90% instability, the simulation grants ×10 EPS. Nobody explains why.',
                  color: 'var(--warn-main)', cond: s => (s.instability||0) >= 70 && (s.instability||0) < 90 },
                { text: 'REDLINE PROXIMITY ALERT. This is not an emergency. Probably.',
                  color: 'var(--danger-main)', cond: s => (s.instability||0) >= 80 && (s.instability||0) < 90 },
                { text: 'WARNING: instability approaching critical. WARNING: the warning system is also unstable.',
                  color: 'var(--danger-main)', cond: s => (s.instability||0) >= 85 },

                // ── Post-prestige ─────────────────────────────────────────
                { text: 'You have ended a run and started again. The machine was unimpressed. It went faster.',
                  cond: s => ((s.prestige&&s.prestige.count)||0) >= 1 },
                { text: 'Legacy Points are the only currency that survives the reset. Spend them carefully.',
                  cond: s => ((s.prestige&&s.prestige.count)||0) >= 1 },
                { text: 'Each prestige makes the next one more expensive. Whoever designed this was not your friend.',
                  cond: s => ((s.prestige&&s.prestige.count)||0) >= 2 },
                { text: 'The neural tree grows. Something feeds on its roots.',
                  cond: s => ((s.prestige&&s.prestige.count)||0) >= 1 },
                { text: 'Previous Operators left fragments. You built on their ruins. Classic.',
                  cond: s => ((s.prestige&&s.prestige.count)||0) >= 1 },

                // ── City active ───────────────────────────────────────────
                { text: 'The citizens of your city do not know they are powering a harvesting engine.',
                  cond: s => s.city&&s.city.slots&&s.city.slots.some(x=>x) },
                { text: 'Adjacency bonuses do not require your residents to consent.',
                  cond: s => s.city&&s.city.slots&&s.city.slots.some(x=>x) },
                { text: 'Civic buildings improve morale. Morale improves compliance. Compliance improves metrics.',
                  cond: s => s.city&&s.city.slots&&s.city.slots.filter(x=>x).length > 5 },
                { text: 'Thermal Decay note: rearranging your city is called "planning". The residents call it something else.',
                  cond: s => s._thermalHeat&&Object.keys(s._thermalHeat).length > 0 },

                // ── Fragments / Slag / Data ───────────────────────────────
                /* ⛔ Read `s.corruptedData` — no underscore — until 2026-09-08, against a
                   state key that is `_corruptedData` (state.js:115). The condition was
                   permanently false, so this line has never fired for anybody. Found while
                   measuring the Corrupted Data rate for step 12. */
                { text: 'Corrupted Data accumulates in the Redline. Something collects it.',
                  cond: s => (s._corruptedData||0) > 0 },
                { text: 'Fragments are crystallised intent. Or crystallised error. The simulation is unclear.',
                  cond: s => (s.fragments||0) > 0 },
                { text: 'Resource Rot has been detected. Your energy is trying to warn you about something.',
                  color: '#cc4400', cond: s => (s.slag||0) > 0 },
                { text: 'The Black Market appreciates your business. It does not appreciate your questions.',
                  color: '#cc3300', cond: s => (s.slag||0) >= 100 },

                // ── Click milestones ──────────────────────────────────────
                { text: 'You have clicked more than ten thousand times. The button is grateful. The button is lying.',
                  cond: s => (s.totalClicks||0) >= 10000 },
                { text: 'Manual input is a choice. The simulation respects choices. The simulation is also tracking them.',
                  cond: s => (s.totalClicks||0) >= 5000 },

                // ── Late game ─────────────────────────────────────────────
                { text: 'At this energy level, the simulation begins to smell different.',
                  cond: s => (s.energy||0) >= 1e12 },
                { text: 'The End is an item in the shop. It is not metaphorical.',
                  cond: s => (s.energy||0) >= 1e20 },
                { text: 'Some Operators purchased The End. None of them filed a report afterwards.',
                  cond: s => (s.energy||0) >= 1e20 },
            ];

            // ── Pick a message appropriate to current game state ──────────
            function _pick() {
                const s = (typeof state !== 'undefined') ? state : {};
                const eligible = _MSG.filter(m => !m.cond || m.cond(s));
                if (!eligible.length) return null;
                return eligible[Math.floor(Math.random() * eligible.length)];
            }

            // ── Fire one tick ─────────────────────────────────────────────
            function _tick() {
                /* ⛔ `isRunning`, NOT `window.isRunning`. It is declared `let isRunning`
                   at script scope (game.js ~:2584), and a script-scope `let` is not a
                   property of `window` — so `window.isRunning` was `undefined` on every
                   tick and this returned every time. The ticker was started, the interval
                   ran, and not one message was ever shown. CLAUDE.md names `isRunning`
                   among the lexical bindings for exactly this reason. */
                if (!isRunning) return;
                /* PLAYTEST_REVIEW §6: nothing speaks to a player who has not done anything yet */
                if (typeof state === 'undefined' || !(_clicked(state) || _automated(state))) return;
                // Don't interrupt an active ticker message
                const t = document.getElementById('world-event-ticker');
                if (t && t.style.display !== 'none' && t.textContent.trim()) return;
                const msg = _pick();
                if (!msg) return;
                if (typeof window.showTicker === 'function') {
                    window.showTicker(msg.text, msg.color || '#6688aa', 9000, true);
                }
            }

            // ── Start ─────────────────────────────────────────────────────
            function start() {
                if (_timerId) return;
                // First message after 90 seconds (let the boot sequence settle)
                setTimeout(_tick, 90000);
                _timerId = setInterval(_tick, INTERVAL_MS);
            }

            function stop() { clearInterval(_timerId); _timerId = null; }

            /* QA hooks (qa_board_onboarding): run one tick now, and list what is eligible */
            return { start, stop, _qaTick: () => _tick(),
                     _qaEligible: () => _MSG.filter(m => !m.cond || m.cond(state)).map(m => m.text) };
        })();
        window.FlavorTicker = FlavorTicker;

        // Wire FlavorTicker into game start
        (function() {
            const _origInit = typeof Game !== 'undefined' && Game.init ? Game.init.bind(Game) : null;
            if (_origInit && !Game._flavorTickerPatched) {
                Game._flavorTickerPatched = true;
                const _prevInit = Game.init.bind(Game);
                Game.init = function(...args) {
                    const result = _prevInit(...args);
                    FlavorTicker.start();
                    return result;
                };
            }

            /* ⛔⛔ AND THE PATCH ABOVE IS NOT ENOUGH — MEASURED, NOT ASSUMED.
               `Game.init()` has exactly one call site (game.js ~:18186), about 17,000
               lines ABOVE this block, so by the time the wrapper exists the only call
               to the thing it wraps has already happened. `tools/probe_flavor_start.js`
               wraps start() and boots normally: startCalls 0, patched true. The ticker
               was started by nothing.

               ⚠ The old `else` fallback could not cover it twice over: it was gated on
               `_origInit` being falsy (and `Game.init` plainly exists, so it never ran),
               and it fired at 3000ms against `isRunning`, which is false while the
               player is still on the menu.

               So wait for the real precondition instead of guessing when it happens.
               The Game.init patch is kept — it is harmless and stays correct for any
               future path that calls init later. */
            let _ftWait = setInterval(() => {
                if (typeof isRunning !== 'undefined' && isRunning) {
                    clearInterval(_ftWait);
                    FlavorTicker.start();   // no-op if the patched init already started it
                }
            }, 2000);
        })();

        // ── 18. ARCHIVIST PARANOIA ACHIEVEMENT (if not already defined) ──────
        // Achievement will be unlocked via _initCopyPasteTrap above.
        // Register it in achievements list
        (function _addArchivistAchievement() {
            function _tryAdd() {
                if (!window.Achieve) { setTimeout(_tryAdd, 800); return; }
                // Check if achievement exists
                if (window.ACHIEVEMENTS && window.ACHIEVEMENTS.find) {
                    // It should be in the list — if not, register dynamically
                }
            }
            _tryAdd();
        })();

        // ── 19. CUSTOM TOOLTIP SYSTEM (V1.20.5.2, pinning added V1.20.5.9) ──
        // Replaces native browser title="" tooltips with styled, animated panels.
        // Usage: add data-tooltip="..." to any element; optional data-tooltip-pos
        // to override placement ("above" | "below" | "left" | "right").
        //
        // V1.20.5.9 — Tooltip Lock:
        //   Press Spacebar while a tooltip is visible to pin it in place.
        //   Pinned tooltips ignore mousemove, mouseout, and scroll — they stay
        //   open until Spacebar is pressed again to release. A "📌 PINNED"
        //   indicator appears inside the tooltip when it is locked.
        //   This allows advanced players to compare City Synergies, Prestige
        //   Mutations, and Compiler spell details side-by-side without the
        //   panel vanishing mid-read.
        const Tooltip = (() => {
            let _el            = null;
            let _hideTimer     = null;
            let _currentTarget = null;
            let _pinned        = false;   // V1.20.5.9: lock state

            function _create() {
                if (_el) return;
                _el = document.createElement('div');
                /* ⛔⛔ THIS USED TO BE id="game-tooltip" TOO, AND SO IS THE OTHER
                   TOOLTIP SYSTEM'S ELEMENT (`Tooltips`, ~:25869). Two elements
                   sharing one id: getElementById returns whichever was created
                   first, the CSS #game-tooltip rules style both, and each module
                   can only ever hide the one it holds a reference to.
                   ⚠ It cost a real investigation two void measurements -- a probe
                   reading getElementById kept getting THIS element while the other
                   system's was the one on screen, and reported "never shown" four
                   times in a row. The class is what the stylesheet actually keys
                   on for this system, so the id was doing nothing but colliding. */
                _el.id = 'game-tooltip-pinnable';
                _el.className = 'game-tooltip';
                _el.style.display = 'none';
                document.body.appendChild(_el);
            }

            function _show(text, x, y) {
                _create();
                clearTimeout(_hideTimer);
                _el.innerHTML = text.replace(/\n/g, '<br>');
                _el.style.cssText = 'display:block; left:' + (x + 14) + 'px; top:' + (y + 14) + 'px;';
                if (_pinned) {
                    _el.classList.add('tooltip-pinned');
                    if (!_el.querySelector('.tooltip-pin-indicator')) {
                        const _ind = document.createElement('div');
                        _ind.className = 'tooltip-pin-indicator';
                        _ind.textContent = '📌 PINNED — press Space to release';
                        _el.appendChild(_ind);
                    }
                } else {
                    _el.classList.remove('tooltip-pinned');
                }
                // Re-trigger fade-in animation each time
                _el.style.animation = 'none';
                void _el.offsetWidth;
                _el.style.animation = '';
                // Clamp to viewport
                requestAnimationFrame(() => {
                    if (!_el) return;
                    const rect = _el.getBoundingClientRect();
                    let tx = x + 14;
                    let ty = y + 14;
                    if (rect.right  > window.innerWidth  - 8) tx = x - rect.width  - 10;
                    if (rect.bottom > window.innerHeight - 8) ty = y - rect.height - 10;
                    _el.style.left = Math.max(6, tx) + 'px';
                    _el.style.top  = Math.max(6, ty) + 'px';
                });
            }

            function _hide() {
                if (_pinned) return;   // pinned tooltip never auto-hides
                clearTimeout(_hideTimer);
                _hideTimer = setTimeout(() => {
                    if (_el) { _el.style.display = 'none'; }
                    _currentTarget = null;
                }, 60);
            }

            // Toggle pin state — called by Spacebar listener
            function _togglePin() {
                if (!_el || _el.style.display === 'none') return;
                _pinned = !_pinned;
                if (_pinned) {
                    clearTimeout(_hideTimer);
                    _el.classList.add('tooltip-pinned');
                    if (!_el.querySelector('.tooltip-pin-indicator')) {
                        const _ind = document.createElement('div');
                        _ind.className = 'tooltip-pin-indicator';
                        _ind.textContent = '📌 PINNED — press Space to release';
                        _el.appendChild(_ind);
                    }
                } else {
                    _el.classList.remove('tooltip-pinned');
                    const _ind = _el.querySelector('.tooltip-pin-indicator');
                    if (_ind) _ind.remove();
                    // Hide after a short delay once unpinned
                    _hide();
                }
            }

            // ── V1.21.0.1 (Phase 4): screen-reader accessibility ──────────
            // data-tooltip is invisible to assistive tech — only native title=
            // is announced. To make the custom tooltip system accessible without
            // forcing a parallel `title` (which would double-render), we derive
            // an aria-label from the data-tooltip text: strip HTML tags, convert
            // <br> to sentence breaks. Runs once at init for static elements and
            // again via a debounced MutationObserver for dynamically-rendered
            // tooltips (shop cards, city chips, compiler spells, …).
            function _deriveAriaLabel(el) {
                if (!el || el.getAttribute('aria-label') || el.getAttribute('aria-labelledby')) return;
                const raw = el.getAttribute('data-tooltip') || '';
                const text = raw
                    .replace(/<br\s*\/?>/gi, '. ')
                    .replace(/<[^>]+>/g, '')
                    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
                    .replace(/\s+/g, ' ')
                    .trim();
                if (text) el.setAttribute('aria-label', text);
            }
            function _scanAria(root) {
                (root || document).querySelectorAll('[data-tooltip]').forEach(_deriveAriaLabel);
            }
            let _ariaScanQueued = false;
            function _queueAriaScan() {
                if (_ariaScanQueued) return;
                _ariaScanQueued = true;
                setTimeout(() => { _ariaScanQueued = false; _scanAria(); }, 500);
            }

            function init() {
                _create();

                // V1.21.0.1: derive aria-labels for all static data-tooltip
                // elements, then watch for dynamically-added ones (debounced).
                _scanAria();
                try {
                    const _obs = new MutationObserver((muts) => {
                        for (const m of muts) {
                            if (m.addedNodes && m.addedNodes.length) { _queueAriaScan(); return; }
                        }
                    });
                    _obs.observe(document.body, { childList: true, subtree: true });
                } catch (e) { /* observer unsupported — static scan still applied */ }

                document.addEventListener('mouseover', (e) => {
                    if (_pinned) return;   // pinned: don't switch target
                    const t = e.target.closest('[data-tooltip]');
                    if (!t) return;
                    if (t === _currentTarget) return;
                    _currentTarget = t;
                    clearTimeout(_hideTimer);
                    _show(t.getAttribute('data-tooltip'), e.clientX, e.clientY);
                }, { passive: true });

                document.addEventListener('mousemove', (e) => {
                    if (_pinned) return;   // pinned: tooltip stays put
                    if (!_el || _el.style.display === 'none') return;
                    const t = e.target.closest('[data-tooltip]');
                    if (!t) { _hide(); return; }
                    if (t !== _currentTarget) {
                        _currentTarget = t;
                        _show(t.getAttribute('data-tooltip'), e.clientX, e.clientY);
                    } else {
                        // Reposition to follow cursor
                        let tx = e.clientX + 14;
                        let ty = e.clientY + 14;
                        const rect = _el.getBoundingClientRect();
                        if (tx + rect.width  > window.innerWidth  - 8) tx = e.clientX - rect.width  - 10;
                        if (ty + rect.height > window.innerHeight - 8) ty = e.clientY - rect.height - 10;
                        _el.style.left = Math.max(6, tx) + 'px';
                        _el.style.top  = Math.max(6, ty) + 'px';
                    }
                }, { passive: true });

                document.addEventListener('mouseout', (e) => {
                    if (_pinned) return;
                    const t = e.target.closest('[data-tooltip]');
                    if (t && t === _currentTarget) _hide();
                }, { passive: true });

                // Hide on scroll only when not pinned
                document.addEventListener('scroll', () => { if (!_pinned) _hide(); }, { passive: true, capture: true });

                // V1.20.5.9: Spacebar to pin/unpin the current tooltip
                // Skips if focus is on an interactive element (input, button, etc.)
                document.addEventListener('keydown', (e) => {
                    if (e.code !== 'Space') return;
                    const tag = e.target && e.target.tagName;
                    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
                    if (!_el || _el.style.display === 'none') return;
                    e.preventDefault();
                    e.stopImmediatePropagation(); // prevent Space from also triggering the main click button
                    _togglePin();
                });
            }

            // refreshAria — render functions may call this after injecting new
            // data-tooltip elements to derive aria-labels immediately rather
            // than waiting for the debounced observer.
            /* ⚠ RELEASING THE PIN HAS TO CLEAR `_pinned`, NOT JUST THE ELEMENT. Every
               handler in this module returns early while pinned, so an element hidden
               from outside with the flag left true would jam the next tooltip as well
               -- one stuck tooltip becoming a dead system. Called by Tooltips.hideAll()
               on every panel change. */
            function release() {
                _pinned = false;
                _currentTarget = null;
                clearTimeout(_hideTimer);
                if (_el) {
                    _el.classList.remove('tooltip-pinned');
                    const _ind = _el.querySelector('.tooltip-pin-indicator');
                    if (_ind) _ind.remove();
                    _el.style.display = 'none';
                }
            }

            return { init, release, refreshAria: _scanAria };
        })();
        window.Tooltip = Tooltip;

        // Wire Tooltip.init into game startup (after DOM is ready)
        (function() {
            if (document.readyState === 'complete' || document.readyState === 'interactive') {
                setTimeout(() => Tooltip.init(), 200);
            } else {
                document.addEventListener('DOMContentLoaded', () => setTimeout(() => Tooltip.init(), 200));
            }
        })();

        /* ═══════════════════════════════════════════════════════════════
           NEXT GOAL WIDGET — updates every 5s to show upcoming goals
           in ~30s (shop item) and ~5min (prestige / PP upgrade)
        ═══════════════════════════════════════════════════════════════ */
        (function _initNextGoalWidget() {
            function _updateNextGoalWidget() {
                const shopEl   = document.getElementById('ngw-line-shop');
                const presEl   = document.getElementById('ngw-line-prestige');
                if (!shopEl || !presEl) return;
                if (typeof state === 'undefined' || typeof ITEMS === 'undefined') return;

                const energy  = state.energy || 0;
                // Compute current EPS (simplified — same formula used in liveEPS displays)
                let pps = 0;
                if (typeof ITEMS !== 'undefined' && typeof Prestige !== 'undefined') {
                    const bon = Prestige.getBonuses ? Prestige.getBonuses() : {};
                    const shopMult = 1 + (bon.shopPowerPct || 0);
                    ITEMS.forEach(i => { if (i.type === 'auto') pps += itemEPS(i) * shopMult; });
                    pps = pps * (bon.autoPct || 1) * (state.multiplier || 1);
                }
                const energy30s = energy + pps * 30;

                // ── Shop: cheapest item player can almost afford in ~30s ─────
                let shopGoal = 'Keep going...';
                if (typeof ITEMS !== 'undefined') {
                    const _ngwShopItem = ITEMS.find(it => {
                        if (it.isEnd) return false;
                        const cost = typeof getItemCost === 'function' ? getItemCost(it, state.items[it.id]||0) : it.cost;
                        return energy < cost && energy30s >= cost;
                    });
                    if (_ngwShopItem) {
                        const _ngwCost = typeof getItemCost === 'function' ? getItemCost(_ngwShopItem, state.items[_ngwShopItem.id]||0) : _ngwShopItem.cost;
                        const _ngwSecs = pps > 0 ? Math.ceil((_ngwCost - energy) / pps) : 0;
                        shopGoal = `~${_ngwSecs}s: ${_ngwShopItem.name}`;
                    }
                }
                shopEl.textContent = '◎ ' + shopGoal;

                // ── Prestige: next prestige threshold or PP upgrade in ~5min ─
                let presGoal = 'Keep going...';
                const pp     = (state.city && state.city.peoplePoints) || 0;
                // Estimate PP rate: roughly 1 PP every few seconds from walkers
                // Use a conservative stored rate if available, or 0
                const ppRate = (state._cachedPPRate || 0);
                const pp5min = pp + ppRate * 300;

                // Check prestige threshold
                if (typeof Prestige !== 'undefined' && Prestige.prestigeCost) {
                    const pCost = Prestige.prestigeCost();
                    const energy5min = energy + pps * 300;
                    if (energy < pCost && energy5min >= pCost) {
                        const secs = pps > 0 ? Math.ceil((pCost - energy) / pps) : 300;
                        const mins = Math.ceil(secs / 60);
                        presGoal = `~${mins}min: PRESTIGE threshold`;
                    }
                }
                // Check PP upgrades if prestige goal not found
                if (presGoal === 'Keep going...' && typeof PP_UPGRADES !== 'undefined') {
                    const _ppUpgs = state.ppUpgrades || {};
                    let _cheapPP = null, _cheapPPCost = Infinity;
                    PP_UPGRADES.forEach(upg => {
                        const lvl = _ppUpgs[upg.id] || 0;
                        const maxLvl = upg.maxLevel || 1;
                        if (lvl >= maxLvl) return;
                        const _upCost = upg.cost * (lvl + 1);
                        if (pp < _upCost && pp5min >= _upCost && _upCost < _cheapPPCost) {
                            _cheapPPCost = _upCost; _cheapPP = upg;
                        }
                    });
                    if (_cheapPP) {
                        presGoal = `~5min: PP — ${_cheapPP.name}`;
                    }
                }
                presEl.textContent = '⬡ ' + presGoal;
            }

            // Run immediately then every 5 seconds
            setTimeout(_updateNextGoalWidget, 2000);
            setInterval(_updateNextGoalWidget, 5000);
        })();

        /* ═══════════════════════════════════════════════════════════════
           NAV TABS — CORE / META / EXTRAS tab switcher
           State stored in window._navTab (no localStorage needed)
        ═══════════════════════════════════════════════════════════════ */
        window.NavTabs = (function() {
            var _current = 'core';
            function show(tab) {
                _current = tab;
                var groups = ['core', 'meta', 'extras'];
                groups.forEach(function(g) {
                    var grp = document.getElementById('nav-group-' + g);
                    var btn = document.getElementById('nav-tab-' + g);
                    if (grp) {
                        if (g === tab) {
                            grp.classList.remove('nav-tab-group-hidden');
                        } else {
                            grp.classList.add('nav-tab-group-hidden');
                        }
                    }
                    if (btn) {
                        if (g === tab) {
                            btn.classList.add('active');
                        } else {
                            btn.classList.remove('active');
                        }
                    }
                });
            }
            function getCurrent() { return _current; }
            // Init: ensure CORE is active on load
            (function() {
                if (document.readyState === 'complete' || document.readyState === 'interactive') {
                    show('core');
                } else {
                    document.addEventListener('DOMContentLoaded', function() { show('core'); });
                }
            })();
            return { show: show, getCurrent: getCurrent };
        })();

        /* ─────────────────────────────────────────────────────────────
           COMPACT NUMBERS TOGGLE
        ───────────────────────────────────────────────────────────── */
        // V1.20.7.9: compact suffix mode ON by default for human-readable numbers (1.23K, 4.56M, 7.89B…)
        window._compactNums = true;
        window.toggleCompactNums = function() {
            window._compactNums = !window._compactNums;
            var btn = document.getElementById('compact-nums-btn');
            if (btn) {
                btn.textContent = window._compactNums ? 'COMPACT \u2713' : 'COMPACT';
                btn.style.borderColor = window._compactNums ? 'var(--brand-main)' : '';
            }
        };

        /* ─────────────────────────────────────────────────────────────
           CALM MODE TOGGLE
        ───────────────────────────────────────────────────────────── */
        window.toggleCalmMode = function() {
            // V1.20.9.4: Calm Mode now uses the standard toggle-switch pattern.
            // The checkbox state is the source of truth; sync the body class to it.
            var cb = document.getElementById('toggle-calmmode');
            var on;
            if (cb) {
                on = cb.checked;
                document.body.classList.toggle('calm-mode', on);
            } else {
                // Fallback for any legacy callers without the checkbox
                on = document.body.classList.toggle('calm-mode');
            }
            var stateLabel = document.getElementById('calmmode-state');
            if (stateLabel) stateLabel.textContent = on ? 'ON' : 'OFF';
            /* \u26d4 CALM MODE DID NOT PERSIST. This function toggled the body class and the
               label and never touched Settings._prefs, and load() never restored it -- so a
               "rest mode" reset itself on every reload, silently. It is the ONLY comfort mode
               in the panel that did not survive a session. Found 2026-09-20 by noticing that
               load() restores 11 state labels while the markup declares 13; the two it skips
               are calmmode and lowgfx, and both were broken. */
            try {
                if (typeof Settings !== 'undefined') { Settings._prefs.calmMode = on; Settings.save(); }
            } catch (e) {}
            // Legacy button (removed in V1.20.9.4) — keep guard for any old DOM
            var legacyBtn = document.getElementById('calm-mode-btn');
            if (legacyBtn) {
                legacyBtn.textContent = on ? 'ON' : 'OFF';
                legacyBtn.style.borderColor = on ? 'var(--brand-main)' : '';
            }
        };


        /* ══════════════════════════════════════════════════════════════════════
           window.Dialog — THE IN-FICTION confirm / prompt / alert
           Owner, 2026-09-21: "replace the Chromium-style confirm popup with an
           in-game/in-fiction UI element", and the same for the user-ID prompt.

           ⛔⛔ THIS IS NOT A RESKIN, BECAUSE ONE OF THEM DOES NOT EXIST IN THE
           SHIPPED BUILD. `window.prompt()` THROWS in Electron. `_safePrompt`
           (~:56) catches that and returns the DEFAULT, which is correct as a
           crash guard and means that in the packaged game "Rename Slot" silently
           does nothing and New Game never asks the player's name at all. The
           owner saw a native prompt, so they were in a browser; the Steam player
           sees no prompt and no rename. A dialog the engine cannot draw is a
           feature that ships as a no-op.

           ▶ PROMISE-BASED, because it has to be. `confirm()` blocks the thread
           and returns a boolean; nothing built out of DOM can do that. Every call
           site therefore has to become async — which is the real work, and why
           the conversion is being done in named batches rather than all at once
           across 17 sites, most of which guard a DESTRUCTIVE action (delete save,
           wipe grid, wipe all data). A botched control-flow conversion there
           deletes somebody's run.

           ⚠ `Dialog.confirm()` resolves FALSE on every dismissal route — Escape,
           the backdrop, Cancel. The one thing it must never do is resolve true by
           accident, because `if (await Dialog.confirm(...))` guards a wipe.
           ⚠ One dialog at a time. A second call while one is open rejects the
           first with `false`/`null` rather than stacking, so a queue cannot form
           behind a modal the player has already answered.
           ══════════════════════════════════════════════════════════════════════ */
        window.Dialog = (function () {
            let _resolve = null;      // resolver for the dialog currently on screen
            let _kind    = null;      // 'confirm' | 'prompt' | 'alert'

            const $ = (id) => document.getElementById(id);

            function _els() {
                return {
                    root:   $('sys-dialog'),
                    title:  $('sys-dialog-title'),
                    body:   $('sys-dialog-body'),
                    wrap:   $('sys-dialog-inputwrap'),
                    lbl:    $('sys-dialog-inputlbl'),
                    input:  $('sys-dialog-input'),
                    ok:     $('sys-dialog-ok'),
                    cancel: $('sys-dialog-cancel'),
                };
            }

            /* settle the open dialog and put the DOM back. Idempotent: calling it
               twice (Escape during a click, say) must not resolve twice. */
            function _close(value) {
                const e = _els();
                if (!e.root) return;
                const r = _resolve; _resolve = null;
                const k = _kind;    _kind = null;
                /* ⚠ 'sys-warn' is NOT removed here: the dialog fades out now (Global 2), and dropping the danger
                   colours on close made a red dialog flash cyan while it faded. open() sets it either way. */
                e.root.classList.remove('open');
                e.root.style.display = 'none';
                if (e.input) e.input.value = '';
                if (e.wrap)  e.wrap.style.display = 'none';
                /* ⚠ release the trap AFTER hiding, so focus returns to whatever
                   opened the dialog rather than to an element inside it */
                if (window.FocusTrap) { try { FocusTrap.release(); } catch (err) {} }
                if (r) r(k === 'prompt' ? (value === false ? null : value) : value);
            }

            function _open(opts) {
                const e = _els();
                /* ⛔ NO SILENT FALLBACK TO THE NATIVE DIALOG. If the markup is
                   missing, a confirm() here would be a browser box on a player's
                   screen — the exact thing being removed — and in Electron a
                   prompt() would throw. Refusing (false / null) is the safe
                   answer for every current call site, because every one of them
                   guards an action, and not doing it is recoverable. */
                if (!e.root || !e.body) return Promise.resolve(opts.kind === 'prompt' ? null : false);

                /* a second dialog does not stack — settle the first as dismissed */
                if (_resolve) _close(_kind === 'prompt' ? null : false);

                _kind = opts.kind;
                e.title.textContent = opts.title || 'SYSTEM';
                e.body.textContent  = opts.body  || '';
                e.root.classList.toggle('sys-warn', !!opts.danger);

                if (opts.kind === 'prompt') {
                    e.wrap.style.display = '';
                    e.lbl.textContent = opts.label || 'INPUT';
                    e.input.value = opts.value || '';
                    e.input.maxLength = opts.maxLength || 24;
                } else {
                    e.wrap.style.display = 'none';
                }

                e.ok.textContent     = opts.okText || 'CONFIRM';
                e.cancel.textContent = opts.cancelText || 'CANCEL';
                /* an alert has one way out, so a CANCEL beside a CONFIRM would be
                   two buttons meaning the same thing */
                e.cancel.style.display = (opts.kind === 'alert') ? 'none' : '';

                e.root.style.display = 'flex';
                e.root.classList.add('open');
                _syncOk();

                /* ⚠ focus the INPUT for a prompt, not the first focusable — the
                   auto-trap registry focuses items[0], which is the Cancel button,
                   and a text box you have to Tab into is a worse dialog than the
                   native one it replaces. */
                if (opts.kind === 'prompt') {
                    /* ⚠ NOT requestAnimationFrame. rAF is serviced at about 1fps in a
                       window that is not compositing — a hidden harness window, and a
                       real window the player has alt-tabbed away from — so a focus
                       scheduled there can be a full second late or arrive after the
                       player has started typing into nothing. A timeout is driven by
                       the event loop and does not care whether anything is painting.
                       ⚠ Twice: once now, and once after the FocusTrap auto-registry
                       has run, because that registry focuses the first focusable
                       element and would otherwise take the caret off the text box. */
                    const _focusInput = () => { try { e.input.focus(); e.input.select(); } catch (err) {} };
                    _focusInput();
                    setTimeout(_focusInput, 0);
                }

                return new Promise((res) => { _resolve = res; });
            }

            /* an empty name is not a name — disable CONFIRM rather than accepting
               it and silently substituting a default, which is what the old
               `|| 'Operator N'` did and is how a player ends up named something
               they never chose */
            function _syncOk() {
                const e = _els();
                if (!e.ok) return;
                if (_kind === 'prompt') e.ok.disabled = !e.input.value.trim();
                else e.ok.disabled = false;
            }

            function _wire() {
                const e = _els();
                if (!e.root || e.root.dataset.wired === '1') return;
                e.root.dataset.wired = '1';

                e.ok.addEventListener('click', () => {
                    if (e.ok.disabled) return;
                    if (_kind === 'prompt') _close(e.input.value.trim());
                    else _close(true);
                });
                e.cancel.addEventListener('click', () => _close(_kind === 'prompt' ? null : false));

                /* clicking the backdrop dismisses; clicking the BOX must not */
                e.root.addEventListener('mousedown', (ev) => {
                    if (ev.target === e.root) _close(_kind === 'prompt' ? null : false);
                });

                e.input.addEventListener('input', _syncOk);

                /* ⚠ capture phase. This game binds Escape and Space at the document
                   level for the panel system and the ACQUIRE button, and Space
                   reaching ACQUIRE while a dialog is open would click it through
                   the modal. Stop both here. */
                document.addEventListener('keydown', (ev) => {
                    if (!_resolve) return;
                    if (ev.key === 'Escape') {
                        ev.preventDefault(); ev.stopImmediatePropagation();
                        _close(_kind === 'prompt' ? null : false);
                    } else if (ev.key === 'Enter') {
                        ev.preventDefault(); ev.stopImmediatePropagation();
                        if (e.ok.disabled) return;
                        if (_kind === 'prompt') _close(e.input.value.trim());
                        else _close(true);
                    } else if (ev.key === ' ' || ev.code === 'Space') {
                        /* let the box have its spaces; block the game's binding */
                        if (document.activeElement !== e.input) ev.preventDefault();
                        ev.stopImmediatePropagation();
                    }
                }, true);
            }

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', _wire);
            } else { _wire(); }

            return {
                confirm: (opts) => _open(Object.assign({ kind: 'confirm' }, opts)),
                prompt:  (opts) => _open(Object.assign({ kind: 'prompt'  }, opts)),
                alert:   (opts) => _open(Object.assign({ kind: 'alert', okText: 'ACKNOWLEDGE' }, opts)),
                isOpen:  () => !!_resolve,
                _close,          /* QA */
                _wire,           /* QA — re-wiring is guarded and idempotent */
            };
        })();

        /* ⭐ THE CLOSING ANIMATION — owner: "the game should feel polished, not
           abrupt." `window.close()` used to be called ~300ms after a save with
           nothing on screen to mark it.
           ⚠ It resolves rather than blocking, so the caller still controls the
           order: save first, then play this, then close. And it is short — 1.1s
           total — because an exit animation you have to WAIT through is its own
           kind of unpolished. */
        window.playShutdown = function () {
            return new Promise((resolve) => {
                const veil = document.getElementById('shutdown-veil');
                if (!veil) { resolve(); return; }
                veil.style.display = 'flex';
                veil.classList.add('on');
                try { if (window.GameMusic && GameMusic.fadeOut) GameMusic.fadeOut(900); } catch (e) {}
                /* ⚠ a timer, not animationend: under reduced motion the animation
                   is suppressed entirely and animationend would never fire, which
                   would strand the player on a black screen instead of exiting.
                   ⚠ 1350 = 0.55s fade + 0.18s of black + 0.62s blip. If either
                   keyframe's timing changes, change this — closing early cuts the
                   blip off, which is the abruptness this exists to remove. */
                setTimeout(resolve, 1350);
            });
        };
